/* Deutsch Trainer — B1 grammar band (lv:4).
   GRAM_B1 = lessons, DRILL_B1 = 8 targeted drills per lesson.
   Explanations in the support language (en/fa); German stays German.  */
window.GRAM_B1=[

/* ============ 1 · temporalsaetze ============ */
{id:'temporalsaetze',ic:'⏱️',lv:4,sk:'Clauses',
 title:{en:'Time clauses: als, wenn, wann',fa:'جمله‌های زمان: als، wenn، wann'},
 sub:{en:'One English "when", three German words',fa:'یک «when» انگلیسی، سه واژهٔ آلمانی'},
 blocks:[
  {type:'text',md:{en:'English has one word for all of this: <b>when</b>. German splits it into three, and the split is not about style — it is about <i>how often</i> and <i>whether you are asking</i>. Get this wrong and the sentence still works, but it marks you as a learner immediately.',
        fa:'انگلیسی برای همهٔ این‌ها یک واژه دارد: <b>when</b>. آلمانی آن را به سه بخش می‌کند، و این تقسیم سلیقه‌ای نیست — به <i>تعداد تکرار</i> و به <i>پرسشی بودن</i> جمله مربوط است.'}},
  {type:'rule',md:{en:'<b>als</b> = one single event or period in the <i>past</i>.<br><b>wenn</b> = present/future, or a <i>repeated</i> past ("whenever").<br><b>wann</b> = only in a question, direct or indirect.',
        fa:'<b>als</b> = یک رویداد یا دورهٔ یگانه در <i>گذشته</i>.<br><b>wenn</b> = حال/آینده، یا گذشتهٔ <i>تکرارشونده</i> («هر وقت»).<br><b>wann</b> = تنها در پرسش، مستقیم یا غیرمستقیم.'}},
  {type:'contrast',cols:[
   {t:'als — once, in the past',md:{en:'„<b>Als</b> ich das erste Mal allein wohnte, habe ich gemerkt, wie teuer Miete ist.“<br>One moment in my life. It happened once and it is over. If you can add „damals“, use <b>als</b>.'}},
   {t:'wenn — every time / in future',md:{en:'„<b>Wenn</b> ich allein wohne, koche ich kaum.“<br>„<b>Immer wenn</b> ich bei meiner Oma war, gab es Kuchen.“<br>Repeated or still to come. If you can add „immer“ or „jedes Mal“, use <b>wenn</b>.'}}]},
  {type:'table',head:['Konjunktion','Meaning','Tense / note'],rows:[
   ['*als','when (one single past event)','Präteritum or Perfekt'],
   ['*wenn','if / when(ever)','present, future, or repeated past'],
   ['*wann','when? (question only)','direct or indirect question'],
   ['*während','while, at the same time','same tense in both clauses'],
   ['*bevor','before','same tense in both clauses'],
   ['*nachdem','after','tense must shift — see below'],
   ['*seitdem','since (and still going on)','Präsens if it continues'],
   ['*sobald','as soon as','earlier action in Perfekt or Präsens'],
   ['*bis','until','Präsens for a point in the future'],
   ['*solange','as long as','same tense in both clauses']],
   cap:{en:'All of these send the verb to the end of their clause.',fa:'همهٔ این‌ها فعل را به آخر جملهٔ خود می‌فرستند.'}},
  {type:'rule',md:{en:'<b>nachdem</b> forces a tense step backwards, because the two actions cannot be at the same level:<br>past: „<b>Nachdem</b> ich gegessen <b>hatte</b>, ging ich spazieren.“ (Plusquamperfekt → Präteritum)<br>now/future: „<b>Nachdem</b> ich gegessen <b>habe</b>, gehe ich spazieren.“ (Perfekt → Präsens)<br><b>bevor</b> never does this: both clauses stay in the same tense.',
        fa:'<b>nachdem</b> یک پله زمان را به عقب می‌برد، چون دو کار نمی‌توانند هم‌سطح باشند: گذشته → ماضی بعید + گذشتهٔ ساده؛ حال/آینده → ماضی نقلی + حال. <b>bevor</b> هرگز چنین نمی‌کند.'}},
  {type:'examples',items:[
   {de:'Als ich nach Deutschland kam, konnte ich kein Wort Deutsch.',en:'When I came to Germany, I couldn’t speak a word of German.',say:'Als ich nach Deutschland kam, konnte ich kein Wort Deutsch.'},
   {de:'Wenn ich zu viel arbeite, werde ich unfreundlich.',en:'When(ever) I work too much, I get unfriendly.',say:'Wenn ich zu viel arbeite, werde ich unfreundlich.'},
   {de:'Ich weiß noch nicht, wann ich Urlaub nehmen kann.',en:'I don’t know yet when I can take holiday.',say:'Ich weiß noch nicht, wann ich Urlaub nehmen kann.'},
   {de:'Seitdem ich jeden Tag lese, fällt mir das Schreiben leichter.',en:'Since I read every day, writing has got easier for me.',say:'Seitdem ich jeden Tag lese, fällt mir das Schreiben leichter.'},
   {de:'Bevor du den Vertrag unterschreibst, solltest du ihn zweimal lesen.',en:'Before you sign the contract, you should read it twice.',say:'Bevor du den Vertrag unterschreibst, solltest du ihn zweimal lesen.'},
   {de:'Nachdem die Preise gestiegen waren, protestierten viele Leute.',en:'After the prices had risen, a lot of people protested.',say:'Nachdem die Preise gestiegen waren, protestierten viele Leute.'}]},
  {type:'warn',md:{en:'Three traps, in order of frequency:<br>1. <b>wann</b> is never a conjunction. „Ich war traurig, <s>wann</s> er ging“ ✗ → „…, <b>als</b> er ging“.<br>2. A single past event is <b>als</b>, not wenn: „<s>Wenn</s> ich ein Kind war…“ ✗ → „<b>Als</b> ich ein Kind war…“.<br>3. „Ich weiß nicht, <s>wenn</s> er kommt“ ✗ — that is an indirect question → <b>wann</b>.',
        fa:'سه دام: ۱) <b>wann</b> هرگز حرف ربط نیست. ۲) رویداد یگانهٔ گذشته <b>als</b> است، نه wenn. ۳) در پرسش غیرمستقیم <b>wann</b> می‌آید، نه wenn.'}},
  {type:'tip',md:{en:'When the time clause comes first, it fills position 1 — so the main verb comes <b>straight after the comma</b>: „Als es dunkel wurde, <b>gingen</b> wir nach Hause.“ Comma, then verb. No exceptions.',
        fa:'وقتی جملهٔ زمان اول بیاید، جایگاه ۱ را پر می‌کند — پس فعل جملهٔ اصلی <b>بلافاصله پس از ویرگول</b> می‌آید: ویرگول، سپس فعل.'}},
  {type:'quiz',q:{en:'„___ ich klein war, hatte ich Angst vor Hunden.“',fa:'«___ ich klein war, hatte ich Angst vor Hunden.»'},
   a:'Als',o:['Wenn','Wann','Wie'],
   ex:{en:'„Ich war klein“ is one single period in the past → <b>Als</b>. <i>Wenn</i> would mean "every time I was small", which makes no sense.',
       fa:'«کوچک بودن» یک دورهٔ یگانه در گذشته است → <b>Als</b>.'}}
 ]},

/* ============ 2 · kausal-konzessiv ============ */
{id:'kausal-konzessiv',ic:'🔀',lv:4,sk:'Connectors',
 title:{en:'weil · denn · obwohl · trotzdem',fa:'weil · denn · obwohl · trotzdem'},
 sub:{en:'Reason and concession — same meaning, different word order',fa:'دلیل و تضاد — معنای یکسان، ترتیب واژهٔ متفاوت'},
 blocks:[
  {type:'text',md:{en:'Four connectors, two meanings, two completely different word orders. <b>weil</b> and <b>denn</b> both give a reason; <b>obwohl</b> and <b>trotzdem</b> both signal "and yet". What separates them inside each pair is purely grammar: one sends the verb to the end, the other does not.',
        fa:'چهار رابط، دو معنا، دو ترتیب واژهٔ کاملاً متفاوت. <b>weil</b> و <b>denn</b> دلیل می‌دهند؛ <b>obwohl</b> و <b>trotzdem</b> تضاد. تفاوت درون هر جفت فقط دستوری است: یکی فعل را به آخر می‌برد، دیگری نه.'}},
  {type:'table',head:['Word','Meaning','What it does to the verb','Example'],rows:[
   ['*weil','because','subordinating → verb *last','Ich gehe nicht mit, weil ich müde *bin.'],
   ['*denn','because / for','links two main clauses → *normal order','Ich gehe nicht mit, denn ich *bin müde.'],
   ['*obwohl','although','subordinating → verb *last','Ich gehe mit, obwohl ich müde *bin.'],
   ['*trotzdem','nevertheless','adverb in position 1 → verb *second','Ich bin müde. Trotzdem *gehe ich mit.']],
   cap:{en:'Four words, two jobs, three word-order patterns. The meaning is the easy part.',
        fa:'چهار واژه، دو کار، سه الگوی ترتیب واژه.'}},
  {type:'contrast',cols:[
   {t:'weil — one sentence, verb last',md:{en:'„Viele kaufen kein Auto mehr, <b>weil</b> das Parken in der Stadt zu teuer <b>ist</b>.“<br>The weil-clause is a <i>part</i> of the sentence. It can also come first: „<b>Weil</b> das Parken zu teuer ist, kaufen viele kein Auto mehr.“'}},
   {t:'denn — two sentences glued together',md:{en:'„Viele kaufen kein Auto mehr, <b>denn</b> das Parken in der Stadt <b>ist</b> zu teuer.“<br><b>denn</b> sits in "position 0" and changes nothing after it. It can <i>never</i> start the sentence.'}}]},
  {type:'contrast',cols:[
   {t:'obwohl — conjunction',md:{en:'„<b>Obwohl</b> der Zug billiger <b>ist</b>, fahren die meisten mit dem Auto.“<br>One sentence, verb at the end of the obwohl-part.'}},
   {t:'trotzdem — adverb',md:{en:'„Der Zug ist billiger. <b>Trotzdem</b> <b>fahren</b> die meisten mit dem Auto.“<br>Two sentences. <b>trotzdem</b> takes position 1, so the verb is pushed to position 2 and the subject comes after it.'}}]},
  {type:'rule',md:{en:'The whole lesson in one grid:<br>• reason + verb last → <b>weil</b><br>• reason + normal order → <b>denn</b><br>• concession + verb last → <b>obwohl</b><br>• concession + inversion → <b>trotzdem</b><br>Pick the meaning first, then the word order. Those two choices are independent.',
        fa:'کل درس در یک جدول: دلیل + فعل آخر → <b>weil</b>؛ دلیل + ترتیب معمولی → <b>denn</b>؛ تضاد + فعل آخر → <b>obwohl</b>؛ تضاد + واژگونی → <b>trotzdem</b>.'}},
  {type:'examples',items:[
   {de:'Ich nehme die Stelle nicht, weil das Gehalt zu niedrig ist.',en:'I’m not taking the job because the salary is too low.',say:'Ich nehme die Stelle nicht, weil das Gehalt zu niedrig ist.'},
   {de:'Ich nehme die Stelle nicht, denn das Gehalt ist zu niedrig.',en:'I’m not taking the job, for the salary is too low.',say:'Ich nehme die Stelle nicht, denn das Gehalt ist zu niedrig.'},
   {de:'Obwohl er kaum gelernt hat, hat er die Prüfung bestanden.',en:'Although he hardly studied, he passed the exam.',say:'Obwohl er kaum gelernt hat, hat er die Prüfung bestanden.'},
   {de:'Das Angebot ist gut. Trotzdem möchte ich noch eine Nacht darüber schlafen.',en:'The offer is good. All the same I’d like to sleep on it.',say:'Das Angebot ist gut. Trotzdem möchte ich noch eine Nacht darüber schlafen.'},
   {de:'Wir haben verloren, obwohl wir deutlich besser gespielt haben.',en:'We lost although we played clearly better.',say:'Wir haben verloren, obwohl wir deutlich besser gespielt haben.'}]},
  {type:'tip',md:{en:'<b>trotzdem</b> behaves exactly like <b>deshalb, deswegen, darum, außerdem, dann</b> — all of them are adverbs that grab position 1 and force the verb into position 2. Learn one, you have the whole family.',
        fa:'<b>trotzdem</b> دقیقاً مثل <b>deshalb، deswegen، darum، außerdem، dann</b> رفتار می‌کند — همه قید هستند، جایگاه ۱ را می‌گیرند و فعل را به جایگاه ۲ می‌رانند.'}},
  {type:'warn',md:{en:'The two errors that cost marks:<br>1. „weil ich <s>bin</s> müde“ ✗ — you hear this from native speakers in spoken German, but in writing the verb must go last: „weil ich müde <b>bin</b>“.<br>2. <b>trotzdem</b> is not a conjunction: „<s>trotzdem</s> ich müde bin“ ✗ → „<b>obwohl</b> ich müde bin“. And „<s>Weil</s> das Gehalt ist zu niedrig“ ✗ → that order needs <b>denn</b>.',
        fa:'دو خطای رایج: ۱) «weil ich bin müde» ✗ — در آلمانی نوشتاری فعل باید آخر باشد. ۲) <b>trotzdem</b> حرف ربط نیست؛ برای جملهٔ پیرو <b>obwohl</b> بگو.'}},
  {type:'quiz',q:{en:'„Es hat stark geregnet. ___ sind wir spazieren gegangen.“',fa:'«Es hat stark geregnet. ___ sind wir spazieren gegangen.»'},
   a:'Trotzdem',o:['Obwohl','Weil','Denn'],
   ex:{en:'The verb <i>sind</i> is in position 2 and the subject follows it — that only works after an adverb. Concession + inversion = <b>Trotzdem</b>.',
       fa:'فعل <i>sind</i> در جایگاه ۲ است و فاعل پس از آن — این فقط پس از قید ممکن است: <b>Trotzdem</b>.'}}
 ]},

/* ============ 3 · finalsaetze ============ */
{id:'finalsaetze',ic:'🎯',lv:4,sk:'Clauses',
 title:{en:'Purpose: um … zu vs damit',fa:'هدف: um … zu در برابر damit'},
 sub:{en:'Why you do something — and who benefits',fa:'چرا کاری می‌کنی — و چه کسی سود می‌برد'},
 blocks:[
  {type:'text',md:{en:'A purpose clause answers <i>Wozu?</i> — "what for?". German has two ways to build one, and which one you may use is decided by a single question: <b>is the subject the same in both halves?</b>',
        fa:'جملهٔ هدف به پرسش <i>Wozu?</i> («برای چه؟») پاسخ می‌دهد. آلمانی دو راه برای ساختنش دارد و انتخاب میان آن‌ها با یک پرسش روشن می‌شود: <b>آیا فاعلِ هر دو بخش یکی است؟</b>'}},
  {type:'rule',md:{en:'Same subject → <b>um … zu</b> + Infinitiv (the subject is not repeated — it cannot be).<br>Different subject → <b>damit</b> + full clause with its own subject and the verb at the end.<br><b>damit</b> is always allowed; <b>um … zu</b> is only allowed when the subjects match.',
        fa:'فاعل یکسان → <b>um … zu</b> + مصدر (فاعل تکرار نمی‌شود — و نمی‌تواند بشود).<br>فاعل متفاوت → <b>damit</b> + جملهٔ کامل با فاعل خودش و فعل در آخر.<br><b>damit</b> همیشه مجاز است؛ <b>um … zu</b> فقط وقتی فاعل‌ها یکی باشند.'}},
  {type:'contrast',cols:[
   {t:'um … zu — one subject',md:{en:'„<b>Ich</b> spare Geld, <b>um</b> im Sommer nach Spanien zu fliegen.“<br>I save, I fly. One actor, so the infinitive has no subject of its own.'}},
   {t:'damit — two subjects',md:{en:'„<b>Ich</b> erkläre es noch einmal, <b>damit alle</b> es verstehen.“<br>I explain, <i>they</i> understand. Two actors, so you need a real clause with a real subject.'}}]},
  {type:'steps',items:[
   {en:'Ask <i>Wozu?</i> and find the purpose.',fa:'بپرس <i>Wozu?</i> و هدف را پیدا کن.'},
   {en:'Compare the two subjects. Same → <b>um … zu</b>. Different → <b>damit</b>.',fa:'دو فاعل را مقایسه کن. یکی → <b>um … zu</b>. متفاوت → <b>damit</b>.'},
   {en:'For <b>um … zu</b>: comma, <b>um</b>, then all the other parts, then <b>zu</b> + Infinitiv at the very end.',fa:'برای <b>um … zu</b>: ویرگول، <b>um</b>، بقیهٔ اجزا، و در آخر <b>zu</b> + مصدر.'},
   {en:'With a separable verb, <b>zu</b> goes <i>inside</i> the word: ab<b>zu</b>sagen, an<b>zu</b>rufen, ein<b>zu</b>kaufen.',fa:'با فعل جداشدنی، <b>zu</b> <i>داخل</i> واژه می‌رود: abzusagen، anzurufen.'}]},
  {type:'table',head:['Purpose clause','Subject','Example'],rows:[
   ['*um … zu','same in both halves','Sie steht früh auf, *um pünktlich im Büro zu sein.'],
   ['*damit','changes','Sie weckt mich früh, *damit ich pünktlich bin.'],
   ['*damit (same subject too)','same — also fine','Sie steht früh auf, *damit sie pünktlich ist.'],
   ['*um … zu with a modal','same','Ich lerne, *um die Zeitung lesen zu können.']],
   cap:{en:'The third row shows that damit is never "wrong" — it is only longer.',
        fa:'ردیف سوم نشان می‌دهد damit هرگز «غلط» نیست — فقط بلندتر است.'}},
  {type:'examples',items:[
   {de:'Ich habe mir ein Wörterbuch gekauft, um die Zeitung lesen zu können.',en:'I bought a dictionary so as to be able to read the newspaper.',say:'Ich habe mir ein Wörterbuch gekauft, um die Zeitung lesen zu können.'},
   {de:'Die Stadt baut neue Radwege, damit weniger Leute mit dem Auto fahren.',en:'The city is building new cycle paths so that fewer people drive.',say:'Die Stadt baut neue Radwege, damit weniger Leute mit dem Auto fahren.'},
   {de:'Er ruft seine Eltern jeden Sonntag an, um sie nicht zu enttäuschen.',en:'He calls his parents every Sunday so as not to disappoint them.',say:'Er ruft seine Eltern jeden Sonntag an, um sie nicht zu enttäuschen.'},
   {de:'Ich schreibe es dir auf, damit du es nicht vergisst.',en:'I’ll write it down for you so that you don’t forget it.',say:'Ich schreibe es dir auf, damit du es nicht vergisst.'},
   {de:'Wir sind früher losgefahren, um den Stau zu vermeiden.',en:'We set off earlier in order to avoid the traffic jam.',say:'Wir sind früher losgefahren, um den Stau zu vermeiden.'}]},
  {type:'warn',md:{en:'English "so that I…" tempts you into a subject where none may stand: „Ich lerne Deutsch, <s>um ich einen Job finde</s>“ ✗. If a subject appears after <b>um</b>, the sentence is broken — switch to <b>damit</b>: „…, <b>damit ich</b> einen Job finde.“ And never translate "for" literally: „<s>für zu lernen</s>“ ✗ → „<b>um zu lernen</b>“.',
        fa:'ساخت انگلیسی «so that I…» تو را به گذاشتن فاعل پس از <b>um</b> وسوسه می‌کند: «um ich einen Job finde» ✗. اگر فاعل لازم است، به <b>damit</b> بروی. و «für zu lernen» ✗ → «um zu lernen».'}},
  {type:'tip',md:{en:'Do not confuse the conjunction <b>damit</b> ("so that") with the da-compound <b>damit</b> ("with it/that"): „Ich kann <b>damit</b> nichts anfangen.“ The conjunction always introduces a clause with a verb at the end; the da-word sits in the middle of a normal sentence.',
        fa:'حرف ربط <b>damit</b> («تا اینکه») را با ترکیب <b>damit</b> («با آن») اشتباه نگیر: حرف ربط همیشه جمله‌ای با فعل در آخر می‌آورد.'}},
  {type:'quiz',q:{en:'„Ich spreche langsam, ___ mich alle verstehen.“',fa:'«Ich spreche langsam, ___ mich alle verstehen.»'},
   a:'damit',o:['um','um zu','weil'],
   ex:{en:'The second half has its own subject (<i>alle</i>), so <b>um … zu</b> is impossible → <b>damit</b>.',
       fa:'بخش دوم فاعل خودش را دارد (<i>alle</i>)، پس <b>um … zu</b> ممکن نیست → <b>damit</b>.'}}
 ]},

/* ============ 4 · konditional ============ */
{id:'konditional',ic:'❓',lv:4,sk:'Clauses',
 title:{en:'Conditions: wenn, falls, sofern',fa:'شرط: wenn، falls، sofern'},
 sub:{en:'Real and unreal — and the wenn you can leave out',fa:'واقعی و غیرواقعی — و آن wenn که می‌توان حذف کرد'},
 blocks:[
  {type:'text',md:{en:'A condition says: <i>this</i> only happens if <i>that</i> is true. German marks it with <b>wenn</b> (neutral, the default), <b>falls</b> (if it should happen — more open, slightly more distant) or <b>sofern</b> (provided that — formal). All three send the verb to the end.',
        fa:'جملهٔ شرط می‌گوید: <i>این</i> تنها اگر <i>آن</i> درست باشد رخ می‌دهد. آلمانی آن را با <b>wenn</b> (پیش‌فرض و بی‌طرف)، <b>falls</b> (در صورتی که — بازتر) یا <b>sofern</b> (به شرطی که — رسمی) نشان می‌دهد. هر سه فعل را به آخر می‌برند.'}},
  {type:'table',head:['Word','Flavour','Example'],rows:[
   ['*wenn','neutral, the normal choice','*Wenn du mir hilfst, bin ich bis morgen fertig.'],
   ['*falls','in case, if it happens at all','*Falls es regnet, feiern wir in der Wohnung.'],
   ['*sofern','provided that (formal, written)','*Sofern alle einverstanden sind, fangen wir um acht an.'],
   ['*ob','NOT a condition — "whether"','Ich weiß nicht, *ob er kommt.']],
   cap:{en:'The last row is the one that causes trouble: English "if" is sometimes ob.',
        fa:'ردیف آخر همان مشکل‌ساز است: «if» انگلیسی گاهی ob می‌شود.'}},
  {type:'rule',md:{en:'Word order comes in two shapes:<br>• condition first → the whole clause is position 1, so the main verb comes right after the comma: „Wenn du Zeit hast, <b>komm</b> doch vorbei.“ / „Wenn es regnet, <b>bleiben</b> wir zu Hause.“<br>• condition second → everything is normal: „Wir <b>bleiben</b> zu Hause, wenn es regnet.“',
        fa:'ترتیب واژه دو شکل دارد: شرط اول → کل جملهٔ شرط جایگاه ۱ است و فعل اصلی بلافاصله پس از ویرگول می‌آید؛ شرط دوم → همه‌چیز معمولی است.'}},
  {type:'contrast',cols:[
   {t:'real condition — Indikativ',md:{en:'„<b>Wenn</b> ich morgen früh <b>aufstehe</b>, <b>schaffe</b> ich den Zug.“<br>It can genuinely happen. Normal present tense on both sides.'}},
   {t:'unreal condition — Konjunktiv II',md:{en:'„<b>Wenn</b> ich reich <b>wäre</b>, <b>würde</b> ich weniger arbeiten.“<br>It is not the case. <i>wäre, hätte, könnte</i> or <i>würde</i> + Infinitiv on both sides.'}}]},
  {type:'rule',md:{en:'You may drop <b>wenn</b> completely and start with the verb instead. The meaning is identical, the tone is a bit more direct — very common in instructions and offers:<br>„<b>Hast</b> du Zeit, komm vorbei.“ = „Wenn du Zeit hast, komm vorbei.“<br>„<b>Hat</b> man kein Auto, wird das Land schnell unpraktisch.“<br>Many speakers add <b>so</b> or <b>dann</b> in the second half: „Hast du Fragen, <b>dann</b> schreib mir.“',
        fa:'می‌توانی <b>wenn</b> را حذف کنی و جمله را با فعل آغاز کنی. معنا یکی است و لحن کمی مستقیم‌تر: «Hast du Zeit, komm vorbei.» بسیاری در بخش دوم <b>dann</b> می‌افزایند.'}},
  {type:'examples',items:[
   {de:'Wenn du mir heute hilfst, helfe ich dir am Wochenende.',en:'If you help me today, I’ll help you at the weekend.',say:'Wenn du mir heute hilfst, helfe ich dir am Wochenende.'},
   {de:'Falls du nicht kommen kannst, schreib mir bitte eine Nachricht.',en:'In case you can’t come, please write me a message.',say:'Falls du nicht kommen kannst, schreib mir bitte eine Nachricht.'},
   {de:'Ich würde das Angebot ablehnen, wenn ich du wäre.',en:'I would turn the offer down if I were you.',say:'Ich würde das Angebot ablehnen, wenn ich du wäre.'},
   {de:'Sofern das Wetter mitspielt, machen wir die Sitzung draußen.',en:'Provided the weather plays along, we’ll hold the meeting outside.',say:'Sofern das Wetter mitspielt, machen wir die Sitzung draußen.'},
   {de:'Brauchst du Hilfe, sag einfach Bescheid.',en:'If you need help, just say so.',say:'Brauchst du Hilfe, sag einfach Bescheid.'}]},
  {type:'warn',md:{en:'English "if" covers two German words, and mixing them up changes the meaning completely:<br>• condition → <b>wenn / falls</b><br>• "whether", after verbs like <i>wissen, fragen, sich sicher sein</i> → <b>ob</b><br>„Ich weiß nicht, <s>wenn</s> er kommt“ ✗ → „…, <b>ob</b> er kommt“ (whether) or „…, <b>wann</b> er kommt“ (at what time).<br>And in the wenn-clause say <b>hätte/wäre</b>, not „haben würde / sein würde“: „Wenn ich Zeit <b>hätte</b>“ ✓.',
        fa:'«if» انگلیسی دو واژهٔ آلمانی است: شرط → <b>wenn/falls</b>؛ «آیا» پس از wissen، fragen → <b>ob</b>. و در جملهٔ wenn بگو <b>hätte/wäre</b>، نه «haben würde».'}},
  {type:'quiz',q:{en:'„___ ich mehr Zeit hätte, würde ich einen Sprachkurs machen.“',fa:'«___ ich mehr Zeit hätte, würde ich einen Sprachkurs machen.»'},
   a:'Wenn',o:['Ob','Als','Wann'],
   ex:{en:'An unreal condition with <i>hätte … würde</i> → <b>Wenn</b>. <i>Ob</i> means "whether" and never starts a condition.',
       fa:'شرط غیرواقعی با <i>hätte … würde</i> → <b>Wenn</b>. <i>Ob</i> یعنی «آیا» و هرگز شرط نمی‌سازد.'}}
 ]},

/* ============ 5 · passiv-basis ============ */
{id:'passiv-basis',ic:'🔁',lv:4,sk:'Passive',
 title:{en:'The passive, first steps',fa:'مجهول، گام‌های نخست'},
 sub:{en:'werden + Partizip II · von vs durch',fa:'werden + اسم مفعول · von در برابر durch'},
 blocks:[
  {type:'text',md:{en:'German uses the passive far more than English, and for a clear reason: often the <i>action</i> matters and the doer is irrelevant, unknown, or politely hidden. News, instructions, rules and job adverts are full of it.',
        fa:'آلمانی بسیار بیشتر از انگلیسی از مجهول استفاده می‌کند، و دلیلش روشن است: اغلب <i>کار</i> مهم است و انجام‌دهنده بی‌اهمیت، ناشناس، یا مؤدبانه پنهان است. خبر، دستور، قانون و آگهی شغلی پر از آن است.'}},
  {type:'rule',md:{en:'Recipe: <b>werden</b> (conjugated) + <b>Partizip II</b> (at the end).<br>Präsens: „Das Haus <b>wird</b> renoviert.“<br>Präteritum: „Das Haus <b>wurde</b> renoviert.“<br>The Partizip II never changes. Only <i>werden</i> moves and agrees.',
        fa:'دستور: <b>werden</b> (صرف‌شده) + <b>اسم مفعول</b> (در آخر). حال: «Das Haus wird renoviert.» گذشته: «Das Haus wurde renoviert.» اسم مفعول هرگز تغییر نمی‌کند.'}},
  {type:'table',head:['','Aktiv','Passiv'],rows:[
   ['Präsens','Man renoviert das Haus.','Das Haus *wird renoviert.'],
   ['Präteritum','Man renovierte das Haus.','Das Haus *wurde renoviert.'],
   ['Perfekt','Man hat das Haus renoviert.','Das Haus *ist renoviert *worden.'],
   ['+ Modalverb','Man muss das Haus renovieren.','Das Haus *muss renoviert *werden.']],
   cap:{en:'In the Perfekt it is worden, never geworden — that is the single most visible passive error.',
        fa:'در ماضی نقلی worden می‌آید، نه geworden — آشکارترین خطای مجهول همین است.'}},
  {type:'steps',items:[
   {en:'Find the Akkusativ object of the active sentence.',fa:'مفعول مستقیم جملهٔ معلوم را پیدا کن.'},
   {en:'Make it the new subject → it switches to Nominativ.',fa:'آن را فاعل جدید کن → به حالت فاعلی می‌رود.'},
   {en:'Verb becomes <b>werden</b> + Partizip II.',fa:'فعل می‌شود <b>werden</b> + اسم مفعول.'},
   {en:'The old subject either disappears, or comes back as <b>von</b> + Dativ.',fa:'فاعل قدیم یا حذف می‌شود، یا با <b>von</b> + حالت مفعولی غیرمستقیم برمی‌گردد.'}]},
  {type:'contrast',cols:[
   {t:'von + Dativ — the agent',md:{en:'Who or what <i>acted</i>: a person, an institution, an animal.<br>„Das Formular wird <b>von der Chefin</b> unterschrieben.“<br>„Der Antrag wurde <b>von der Stadt</b> abgelehnt.“'}},
   {t:'durch + Akkusativ — the means or cause',md:{en:'What the action happened <i>through</i>: an event, a force, a method.<br>„Die Straße wurde <b>durch das Unwetter</b> beschädigt.“<br>„Das Problem wurde <b>durch ein Update</b> gelöst.“'}}]},
  {type:'examples',items:[
   {de:'In Deutschland wird viel über ein Tempolimit diskutiert.',en:'In Germany a speed limit is discussed a lot.',say:'In Deutschland wird viel über ein Tempolimit diskutiert.'},
   {de:'Die Entscheidung wurde letzte Woche ohne uns getroffen.',en:'The decision was taken last week without us.',say:'Die Entscheidung wurde letzte Woche ohne uns getroffen.'},
   {de:'Mir wurde gesagt, dass der Kurs schon voll ist.',en:'I was told that the course is already full.',say:'Mir wurde gesagt, dass der Kurs schon voll ist.'},
   {de:'Die Brücke ist erst letztes Jahr gebaut worden.',en:'The bridge was only built last year.',say:'Die Brücke ist erst letztes Jahr gebaut worden.'},
   {de:'Diese Aufgabe muss bis Freitag erledigt werden.',en:'This task has to be done by Friday.',say:'Diese Aufgabe muss bis Freitag erledigt werden.'},
   {de:'Hier darf nicht geparkt werden.',en:'Parking is not allowed here.',say:'Hier darf nicht geparkt werden.'}]},
  {type:'warn',md:{en:'Two traps:<br>1. <b>worden</b>, not geworden. „Das Haus ist renoviert <s>geworden</s>“ ✗ → „… renoviert <b>worden</b>“. Keep <i>geworden</i> for the full verb: „Er ist Arzt geworden.“<br>2. Dativ verbs keep their Dativ. <i>helfen</i> takes Dativ, so the person can never become the subject: „<s>Ich wurde geholfen</s>“ ✗ → „<b>Mir</b> wurde geholfen.“ Same with <i>danken, gratulieren, zuhören</i>.',
        fa:'دو دام: ۱) <b>worden</b>، نه geworden. ۲) فعل‌های داتیو داتیو خود را نگه می‌دارند: «Mir wurde geholfen» ✓، نه «Ich wurde geholfen».'}},
  {type:'tip',md:{en:'Careful with <b>sein</b> + Partizip II — that is a <i>state</i>, not an action: „Das Fenster <b>ist</b> geöffnet“ (it stands open) vs „Das Fenster <b>wird</b> geöffnet“ (someone is opening it right now).',
        fa:'با <b>sein</b> + اسم مفعول دقت کن — آن <i>حالت</i> است نه کار: «Das Fenster ist geöffnet» (باز است) در برابر «Das Fenster wird geöffnet» (کسی دارد بازش می‌کند).'}},
  {type:'quiz',q:{en:'„Der Film ___ 1998 in Berlin gedreht.“',fa:'«Der Film ___ 1998 in Berlin gedreht.»'},
   a:'wurde',o:['wird','war','hat'],
   ex:{en:'A finished action in the past, passive → Präteritum of werden = <b>wurde</b>. <i>war gedreht</i> would describe a state, <i>hat gedreht</i> is active.',
       fa:'کار تمام‌شده در گذشته، مجهول → گذشتهٔ werden = <b>wurde</b>.'}}
 ]}
,

/* ============ 6 · konjunktiv2-basis ============ */
{id:'konjunktiv2-basis',ic:'🌙',lv:4,sk:'Konjunktiv',
 title:{en:'Politeness and wishes: Konjunktiv II',fa:'ادب و آرزو: وجه شرطی'},
 sub:{en:'könnte, hätte, wäre, würde',fa:'könnte، hätte، wäre، würde'},
 blocks:[
  {type:'text',md:{en:'Konjunktiv II is the "unreal" mode. It does two jobs that a learner needs every single day: it makes a request <b>polite</b>, and it talks about things that are <b>not the case</b> — wishes, advice, hypotheses. The indicative („Geben Sie mir Wasser“) sounds like an order; Konjunktiv II („Könnten Sie mir Wasser geben?“) sounds like a human being.',
        fa:'وجه شرطی حالت «غیرواقعی» است و دو کار می‌کند که هر روز به آن نیاز داری: درخواست را <b>مؤدبانه</b> می‌کند، و از چیزهایی می‌گوید که <b>واقعی نیستند</b> — آرزو، نصیحت، فرض.'}},
  {type:'table',head:['Verb','Konjunktiv II','Typical use'],rows:[
   ['sein','*wäre','Es *wäre schön, dich wiederzusehen.'],
   ['haben','*hätte','Ich *hätte gern einen Termin.'],
   ['werden','*würde','Ich *würde das nicht machen.'],
   ['können','*könnte','*Könnten Sie mir helfen?'],
   ['müssen','*müsste','Du *müsstest mehr schlafen.'],
   ['dürfen','*dürfte','*Dürfte ich kurz telefonieren?'],
   ['sollen','*sollte','Du *solltest mit ihm reden.'],
   ['mögen','*möchte','Ich *möchte bitte zahlen.'],
   ['wissen','*wüsste','Ich *wüsste nicht, was ich sagen soll.']],
   cap:{en:'These nine are worth learning by heart — they cover almost all real use at B1.',
        fa:'این نُه مورد ارزش حفظ کردن دارند — تقریباً همهٔ کاربرد واقعی در سطح B1 را می‌پوشانند.'}},
  {type:'rule',md:{en:'For every <i>other</i> verb, use <b>würde</b> + Infinitiv. The old one-word forms (ginge, käme, tränke) exist, but outside <i>sein, haben, werden, wissen</i> and the modals they sound bookish:<br>„Ich <b>würde</b> dir sofort <b>helfen</b>, wenn ich Zeit hätte.“ ✓<br>„Ich <b>hülfe</b> dir sofort…“ — grammatically fine, but nobody talks like this.',
        fa:'برای همهٔ فعل‌های <i>دیگر</i> از <b>würde</b> + مصدر استفاده کن. شکل‌های یک‌واژه‌ای قدیمی (ginge، käme) وجود دارند ولی بیرون از sein، haben، werden، wissen و فعل‌های کمکی وجهی کتابی به گوش می‌رسند.'}},
  {type:'contrast',cols:[
   {t:'Indikativ — direct, sometimes rude',md:{en:'„<b>Haben</b> Sie morgen Zeit?“<br>„<b>Können</b> Sie das wiederholen?“<br>„<b>Ich will</b> einen Kaffee.“<br>Not wrong — but flat, and in a shop or office slightly abrupt.'}},
   {t:'Konjunktiv II — polite, soft',md:{en:'„<b>Hätten</b> Sie morgen Zeit?“<br>„<b>Könnten</b> Sie das wiederholen?“<br>„<b>Ich hätte gern</b> einen Kaffee.“<br>Same content, one step back. This is the register of service, work and strangers.'}}]},
  {type:'steps',items:[
   {en:'Ordering or asking for something: <b>Ich hätte gern …</b> / <b>Ich möchte …</b>',fa:'سفارش یا درخواست: <b>Ich hätte gern …</b> / <b>Ich möchte …</b>'},
   {en:'Asking a favour: <b>Könnten Sie …?</b> / <b>Würden Sie …?</b> / <b>Dürfte ich …?</b>',fa:'خواهش: <b>Könnten Sie …?</b> / <b>Würden Sie …?</b>'},
   {en:'Giving advice: <b>Du solltest …</b> / <b>An deiner Stelle würde ich …</b>',fa:'نصیحت: <b>Du solltest …</b> / <b>An deiner Stelle würde ich …</b>'},
   {en:'A wish: <b>Ich wünschte, …</b> / <b>Es wäre schön, wenn …</b>',fa:'آرزو: <b>Ich wünschte, …</b> / <b>Es wäre schön, wenn …</b>'}]},
  {type:'examples',items:[
   {de:'Könnten Sie das bitte noch einmal erklären?',en:'Could you please explain that once more?',say:'Könnten Sie das bitte noch einmal erklären?'},
   {de:'Ich hätte gern einen Termin am Freitagvormittag.',en:'I’d like an appointment on Friday morning.',say:'Ich hätte gern einen Termin am Freitagvormittag.'},
   {de:'An deiner Stelle würde ich das Angebot ablehnen.',en:'In your position I would turn the offer down.',say:'An deiner Stelle würde ich das Angebot ablehnen.'},
   {de:'Es wäre besser, wenn wir früher anfangen würden.',en:'It would be better if we started earlier.',say:'Es wäre besser, wenn wir früher anfangen würden.'},
   {de:'Du solltest wirklich mehr schlafen, wenn du gesund bleiben willst.',en:'You really should sleep more if you want to stay healthy.',say:'Du solltest wirklich mehr schlafen, wenn du gesund bleiben willst.'},
   {de:'Hätten Sie morgen Zeit für ein kurzes Gespräch?',en:'Would you have time for a short talk tomorrow?',say:'Hätten Sie morgen Zeit für ein kurzes Gespräch?'}]},
  {type:'warn',md:{en:'Three things learners get wrong:<br>1. <b>hätte gern</b> ≠ <b>habe gern</b>. „Ich <b>habe</b> Kaffee gern“ = I like coffee (in general). „Ich <b>hätte</b> gern Kaffee“ = I’d like a coffee (now, please).<br>2. <b>möchte</b> is <i>already</i> Konjunktiv II — never „möchtete“, and the past is „wollte“.<br>3. Do not pile up <b>würde</b> where a short form exists: „Wenn ich Zeit <b>hätte</b>“ ✓, „Wenn ich Zeit <s>haben würde</s>“ ✗.',
        fa:'سه خطا: ۱) <b>hätte gern</b> با <b>habe gern</b> یکی نیست. ۲) <b>möchte</b> خودش وجه شرطی است — «möchtete» وجود ندارد. ۳) جایی که شکل کوتاه هست، <b>würde</b> نگذار: «Wenn ich Zeit hätte» ✓.'}},
  {type:'quiz',q:{en:'„___ Sie mir bitte beim Formular helfen?“ (as polite as possible)',fa:'«___ Sie mir bitte beim Formular helfen?» (مؤدبانه‌ترین شکل)'},
   a:'Könnten',o:['Konnten','Könntet','Könnte'],
   ex:{en:'Polite request with <i>Sie</i> → <b>Könnten</b>. <i>Konnten</i> is the past indicative ("were you able to"), <i>könntet</i> belongs to <i>ihr</i>, <i>könnte</i> to <i>ich/er</i>.',
       fa:'درخواست مؤدبانه با <i>Sie</i> → <b>Könnten</b>. <i>Konnten</i> گذشتهٔ اخباری است و <i>könntet</i> برای <i>ihr</i>.'}}
 ]},

/* ============ 7 · relativ-was-wo ============ */
{id:'relativ-was-wo',ic:'🪢',lv:4,sk:'Clauses',
 title:{en:'Relative clauses with was and wo',fa:'جملهٔ وصفی با was و wo'},
 sub:{en:'alles, was … · die Stadt, wo …',fa:'alles, was … · die Stadt, wo …'},
 blocks:[
  {type:'text',md:{en:'You already build relative clauses with <i>der, den, dem</i>. But those pronouns need a noun with a gender to agree with. Sometimes there is no such noun — the clause refers to <b>everything, nothing, something</b>, or to <b>a whole idea</b>. That is where <b>was</b> steps in. And for places, <b>wo</b> saves you a preposition.',
        fa:'تو جملهٔ وصفی را با <i>der، den، dem</i> می‌سازی. ولی آن ضمایر به اسمی با جنس دستوری نیاز دارند. گاهی چنین اسمی وجود ندارد — جمله به <b>همه‌چیز، هیچ‌چیز، چیزی</b> یا به <b>یک ایدهٔ کامل</b> برمی‌گردد. آنجا <b>was</b> وارد می‌شود.'}},
  {type:'rule',md:{en:'Use <b>was</b> after:<br>• the indefinites <b>alles, nichts, etwas, vieles, weniges, manches</b><br>• the pronoun <b>das</b> („das, was ich meine“)<br>• a neuter superlative: <b>das Beste, das Schönste, das Einzige</b><br>• a <b>whole preceding clause</b> („Er kam zu spät, <b>was</b> alle geärgert hat.“)',
        fa:'<b>was</b> را به کار ببر پس از: نامعین‌های <b>alles، nichts، etwas، vieles، weniges</b>؛ ضمیر <b>das</b>؛ صفت برترین خنثی (<b>das Beste</b>)؛ و پس از <b>یک جملهٔ کامل</b>.'}},
  {type:'contrast',cols:[
   {t:'das — a real noun in front',md:{en:'„Das <b>Buch</b>, <b>das</b> ich gelesen habe, war spannend.“<br>There is a noun (<i>das Buch</i>) with gender, number and a case job. Use a <i>der/die/das</i> pronoun.'}},
   {t:'was — no noun to agree with',md:{en:'„<b>Alles</b>, <b>was</b> ich gelesen habe, war spannend.“<br>„Er hat sich nicht entschuldigt, <b>was</b> ich unhöflich finde.“<br>Nothing with a gender → <b>was</b>.'}}]},
  {type:'rule',md:{en:'If the verb inside the clause needs a preposition, <b>was</b> fuses with it into a <b>wo(r)-</b> word, exactly like the da-compounds:<br>„Das ist etwas, <b>worüber</b> wir reden müssen.“ (reden über)<br>„Es gibt nichts, <b>worauf</b> ich mich mehr freue.“ (sich freuen auf)<br>Never „über was“ in careful German.',
        fa:'اگر فعل درون جمله به حرف اضافه نیاز دارد، <b>was</b> با آن در واژهٔ <b>wo(r)-</b> ذوب می‌شود: «etwas, worüber wir reden müssen». در آلمانی دقیق «über was» نگو.'}},
  {type:'rule',md:{en:'For <b>places</b>, <b>wo</b> replaces preposition + relative pronoun:<br>„die Stadt, <b>in der</b> ich wohne“ = „die Stadt, <b>wo</b> ich wohne“<br>„das Café, <b>in dem</b> wir uns trafen“ = „das Café, <b>wo</b> wir uns trafen“<br>Both are correct; <b>wo</b> is shorter and very common in speech. For movement, use <b>wohin</b> / <b>woher</b>: „der Ort, <b>wohin</b> wir fahren“.',
        fa:'برای <b>مکان</b>، <b>wo</b> جای حرف اضافه + ضمیر وصفی را می‌گیرد: «die Stadt, in der ich wohne» = «die Stadt, wo ich wohne». برای حرکت <b>wohin</b> / <b>woher</b>.'}},
  {type:'examples',items:[
   {de:'Alles, was er über die Firma sagt, klingt übertrieben.',en:'Everything he says about the company sounds exaggerated.',say:'Alles, was er über die Firma sagt, klingt übertrieben.'},
   {de:'Es gibt nichts, was mich mehr ärgert als Unpünktlichkeit.',en:'There is nothing that annoys me more than unpunctuality.',say:'Es gibt nichts, was mich mehr ärgert als Unpünktlichkeit.'},
   {de:'Das ist das Beste, was mir diese Woche passiert ist.',en:'That’s the best thing that has happened to me this week.',say:'Das ist das Beste, was mir diese Woche passiert ist.'},
   {de:'Sie hat ohne mich entschieden, was ich wirklich unfair finde.',en:'She decided without me, which I find really unfair.',say:'Sie hat ohne mich entschieden, was ich wirklich unfair finde.'},
   {de:'Das Dorf, wo ich aufgewachsen bin, hat nur dreihundert Einwohner.',en:'The village where I grew up has only three hundred inhabitants.',say:'Das Dorf, wo ich aufgewachsen bin, hat nur dreihundert Einwohner.'},
   {de:'Das ist genau das, worüber ich mit dir sprechen wollte.',en:'That’s exactly what I wanted to talk to you about.',say:'Das ist genau das, worüber ich mit dir sprechen wollte.'}]},
  {type:'warn',md:{en:'The classic errors:<br>1. „Alles, <s>das</s> ich weiß…“ ✗ → <b>was</b>. After <i>alles/nichts/etwas</i> it is always <b>was</b>.<br>2. <b>was</b> never refers to a person: „der Mann, <s>was</s> dort steht“ ✗ → „der Mann, <b>der</b> dort steht“.<br>3. The comma is not optional: German always puts a comma before the relative clause, even a two-word one.<br>4. Do not mix up <b>was</b> (relative) with <b>dass</b> (that-clause): „Ich finde, <b>dass</b> er recht hat“ ≠ „…, <b>was</b> er sagt“.',
        fa:'خطاهای کلاسیک: ۱) پس از alles/nichts/etwas همیشه <b>was</b> است، نه das. ۲) <b>was</b> هرگز به شخص برنمی‌گردد. ۳) ویرگول پیش از جملهٔ وصفی اجباری است. ۴) <b>was</b> را با <b>dass</b> اشتباه نگیر.'}},
  {type:'quiz',q:{en:'„Es gibt nichts, ___ ich lieber tun würde.“',fa:'«Es gibt nichts, ___ ich lieber tun würde.»'},
   a:'was',o:['das','dass','welches'],
   ex:{en:'<i>nichts</i> has no gender for a pronoun to agree with → <b>was</b>. <i>dass</i> is a conjunction, not a relative pronoun.',
       fa:'<i>nichts</i> جنس دستوری ندارد → <b>was</b>. <i>dass</i> حرف ربط است، نه ضمیر وصفی.'}}
 ]},

/* ============ 8 · adjektiv-komplett ============ */
{id:'adjektiv-komplett',ic:'🎨',lv:4,sk:'Adjectives',
 title:{en:'The complete adjective endings',fa:'پایانه‌های کامل صفت'},
 sub:{en:'One table instead of three grids',fa:'یک جدول به‌جای سه شبکهٔ حفظی'},
 blocks:[
  {type:'text',md:{en:'Most books give you three tables — weak, mixed, strong — and ask you to memorise 48 boxes. You do not need that. There is one idea behind all of it: <b>the case must be visible exactly once</b>. If the article already shows it, the adjective relaxes. If the article shows nothing, the adjective has to do the work.',
        fa:'بیشتر کتاب‌ها سه جدول می‌دهند — ضعیف، آمیخته، قوی — و از تو می‌خواهند ۴۸ خانه را حفظ کنی. لازم نیست. یک ایده پشت همهٔ آن است: <b>حالت باید دقیقاً یک بار دیده شود</b>. اگر حرف تعریف آن را نشان دهد، صفت آسوده می‌شود؛ اگر نشان ندهد، صفت باید کار را انجام دهد.'}},
  {type:'rule',md:{en:'The whole system in three lines:<br>1. After <b>der/die/das, dieser, jeder, alle, welcher</b> the case is already clear → the adjective takes only <b>-e</b> or <b>-en</b>.<br>2. After <b>ein/kein/mein/dein/…</b> the ending is the same <i>except</i> in the three spots where <i>ein</i> itself shows nothing: there the adjective borrows the article ending (<b>-er, -es, -es</b>).<br>3. With <b>no article at all</b>, the adjective simply takes the der-ending it would have had: <i>guter Wein, gutes Brot, guten Wein, gutem Wein, guten Freunden</i>.',
        fa:'کل سیستم در سه خط: ۱) پس از der/die/das، dieser، jeder، alle حالت روشن است → صفت فقط <b>-e</b> یا <b>-en</b> می‌گیرد. ۲) پس از ein/kein/mein همان است، جز سه جایی که خود ein چیزی نشان نمی‌دهد و صفت پایانهٔ حرف تعریف را قرض می‌گیرد. ۳) بی هیچ حرف تعریف، صفت همان پایانهٔ der را می‌گیرد.'}},
  {type:'table',head:['Case','m','f','n','Plural'],rows:[
   ['Nominativ','der gut*e','die gut*e','das gut*e','die gut*en'],
   ['Akkusativ','den gut*en','die gut*e','das gut*e','die gut*en'],
   ['Dativ','dem gut*en','der gut*en','dem gut*en','den gut*en'],
   ['Genitiv','des gut*en','der gut*en','des gut*en','der gut*en']],
   cap:{en:'Weak: only -e or -en. The five -e boxes form an L in the top left — Nom m/f/n and Akk f/n. Everything else is -en.',
        fa:'ضعیف: تنها -e یا -en. پنج خانهٔ -e در بالا-چپ یک L می‌سازند؛ بقیه همه -en.'}},
  {type:'table',head:['Case','m','f','n','Plural'],rows:[
   ['Nominativ','ein gut*er','eine gute','ein gut*es','keine guten'],
   ['Akkusativ','einen guten','eine gute','ein gut*es','keine guten'],
   ['Dativ','einem guten','einer guten','einem guten','keinen guten'],
   ['Genitiv','eines guten','einer guten','eines guten','keiner guten']],
   cap:{en:'Mixed: identical to the weak table except the three highlighted boxes — exactly where ein has no ending of its own.',
        fa:'آمیخته: مثل جدول ضعیف، جز سه خانهٔ برجسته — همان‌جا که ein پایانه‌ای ندارد.'}},
  {type:'table',head:['Case','m','f','n','Plural'],rows:[
   ['Nominativ','gut*er Wein','gut*e Milch','gut*es Brot','gut*e Weine'],
   ['Akkusativ','gut*en Wein','gut*e Milch','gut*es Brot','gut*e Weine'],
   ['Dativ','gut*em Wein','gut*er Milch','gut*em Brot','gut*en Weinen'],
   ['Genitiv','guten Weines','gut*er Milch','guten Brotes','gut*er Weine']],
   cap:{en:'Strong: the adjective wears the der-endings itself (der→-er, das→-es, dem→-em). Only the masc./neut. genitive breaks the pattern with -en.',
        fa:'قوی: صفت خودش پایانه‌های der را می‌پوشد. تنها اضافی مذکر/خنثی با -en از الگو بیرون است.'}},
  {type:'steps',items:[
   {en:'Is there an article word in front? No → strong endings (der-endings on the adjective).',fa:'آیا حرف تعریفی در پیش هست؟ نه → پایانه‌های قوی.'},
   {en:'Yes, and it is der/die/das/dieser/jeder/alle → only -e or -en (weak table).',fa:'بله، و der/die/das/dieser/jeder/alle است → فقط -e یا -en.'},
   {en:'Yes, and it is ein/kein/mein → same as weak, but -er for Nom m and -es for Nom/Akk n.',fa:'بله، و ein/kein/mein است → مثل ضعیف، ولی -er برای فاعلی مذکر و -es برای خنثی.'},
   {en:'Several adjectives in a row all take the same ending: „ein <b>schöner großer</b> Garten“.',fa:'چند صفت پشت‌سرهم همه یک پایانه می‌گیرند: «ein schöner großer Garten».'}]},
  {type:'examples',items:[
   {de:'Ich suche eine günstige Wohnung mit einem kleinen Balkon.',en:'I’m looking for a cheap flat with a small balcony.',say:'Ich suche eine günstige Wohnung mit einem kleinen Balkon.'},
   {de:'Guter Kaffee ist mir wichtiger als schnelles Internet.',en:'Good coffee matters more to me than fast internet.',say:'Guter Kaffee ist mir wichtiger als schnelles Internet.'},
   {de:'Mit dem alten Auto würde ich keine lange Reise machen.',en:'I wouldn’t make a long trip with that old car.',say:'Mit dem alten Auto würde ich keine lange Reise machen.'},
   {de:'Viele junge Leute wollen heute kein eigenes Auto mehr.',en:'A lot of young people today don’t want their own car any more.',say:'Viele junge Leute wollen heute kein eigenes Auto mehr.'},
   {de:'Nach der langen Diskussion hatten wir noch keine gute Lösung.',en:'After the long discussion we still had no good solution.',say:'Nach der langen Diskussion hatten wir noch keine gute Lösung.'},
   {de:'Sie hat mir einen interessanten Artikel über erneuerbare Energien geschickt.',en:'She sent me an interesting article about renewable energy.',say:'Sie hat mir einen interessanten Artikel über erneuerbare Energien geschickt.'}]},
  {type:'warn',md:{en:'The plural quantifiers are where good students lose points. <b>viele, wenige, einige, mehrere, andere, ein paar</b> do <i>not</i> count as articles, so the adjective after them is <b>strong</b>:<br>„viele <b>junge</b> Leute“ ✓ — „viele <s>jungen</s> Leute“ ✗<br>But <b>alle</b> <i>is</i> an article word: „alle <b>jungen</b> Leute“ ✓.<br>And after <b>etwas/nichts/viel/wenig</b> the adjective becomes a capitalised noun: „etwas <b>Neues</b>“, „nichts <b>Besonderes</b>“.',
        fa:'کمیت‌نماهای جمع تله‌اند: <b>viele، wenige، einige، mehrere، andere</b> حرف تعریف نیستند، پس صفت پس از آن‌ها <b>قوی</b> است: «viele junge Leute» ✓. ولی <b>alle</b> حرف تعریف است: «alle jungen Leute» ✓.'}},
  {type:'tip',md:{en:'Fast self-check: say the article and the adjective together and ask „where is the case visible?“ It must be visible once — and only the first word in the group ever shows it. <i>dem</i> shows Dativ, so <i>alten</i> can stay lazy; <i>ein</i> shows nothing, so <i>guter</i> must speak up.',
        fa:'بررسی سریع: حرف تعریف و صفت را با هم بگو و بپرس «حالت کجا دیده می‌شود؟» باید یک بار دیده شود — و تنها واژهٔ نخست گروه آن را نشان می‌دهد.'}},
  {type:'quiz',q:{en:'„Ich habe mit ___ Freunden gesprochen.“ (no article, Dativ plural, gut)',fa:'«Ich habe mit ___ Freunden gesprochen.» (بی حرف تعریف، داتیو جمع، gut)'},
   a:'guten',o:['gute','guter','gutem'],
   ex:{en:'No article → strong endings. Dativ plural article would be <i>den</i>, so the adjective takes <b>-en</b>: <b>guten</b> Freunden.',
       fa:'بی حرف تعریف → پایانهٔ قوی. حرف تعریف داتیو جمع <i>den</i> است، پس صفت <b>-en</b> می‌گیرد.'}}
 ]},

/* ============ 9 · partizip-adjektiv-b1 ============ */
{id:'partizip-adjektiv-b1',ic:'🎭',lv:4,sk:'Adjectives',
 title:{en:'Participles as adjectives',fa:'اسم فاعل و اسم مفعول در نقش صفت'},
 sub:{en:'das weinende Kind · das gekochte Ei',fa:'das weinende Kind · das gekochte Ei'},
 blocks:[
  {type:'text',md:{en:'German can put a verb directly in front of a noun by turning it into a participle. There are two of them and they point in opposite directions: <b>Partizip I</b> says the noun <i>is doing</i> it, <b>Partizip II</b> says the noun <i>has had</i> it done.',
        fa:'آلمانی می‌تواند فعل را با تبدیل به وجه وصفی مستقیماً پیش از اسم بگذارد. دو نوع دارد و در دو جهت مخالف: <b>Partizip I</b> می‌گوید اسم خودش آن کار را <i>می‌کند</i>، <b>Partizip II</b> می‌گوید آن کار <i>بر او انجام شده</i>.'}},
  {type:'rule',md:{en:'Forming them is easy:<br>• <b>Partizip I</b> = Infinitiv + <b>-d</b> → weinen → <b>weinend</b>, lachen → <b>lachend</b>, steigen → <b>steigend</b><br>• <b>Partizip II</b> = the form you already use in the Perfekt → kochen → <b>gekocht</b>, einladen → <b>eingeladen</b><br>Then both behave like <i>any</i> adjective and take the normal endings.',
        fa:'ساختن آسان است: <b>Partizip I</b> = مصدر + <b>-d</b> (weinen → weinend)؛ <b>Partizip II</b> = همان شکلی که در ماضی نقلی به کار می‌بری (kochen → gekocht). سپس هر دو مثل <i>هر</i> صفت پایانه می‌گیرند.'}},
  {type:'contrast',cols:[
   {t:'Partizip I — active, in progress',md:{en:'„das <b>weinende</b> Kind“ — the child is crying, right now.<br>„<b>kochendes</b> Wasser“ — the water is boiling.<br>„die <b>steigenden</b> Mieten“ — the rents are going up.<br>Translate with <i>-ing</i>.'}},
   {t:'Partizip II — passive, finished',md:{en:'„das <b>gekochte</b> Ei“ — someone boiled it; it is done.<br>„das <b>reparierte</b> Fahrrad“ — it has been repaired.<br>„die <b>eingeladenen</b> Gäste“ — they were invited.<br>Translate with <i>-ed</i>.'}}]},
  {type:'table',head:['Verb','Partizip I','Partizip II'],rows:[
   ['weinen','das wein*ende Kind','—'],
   ['kochen','*kochendes Wasser (boiling)','das *gekochte Ei (boiled)'],
   ['schlafen','das schlaf*ende Baby','—'],
   ['einladen','—','die *eingeladenen Gäste'],
   ['reparieren','—','das *reparierte Fahrrad'],
   ['ausfüllen','—','das *ausgefüllte Formular'],
   ['bellen','ein bell*ender Hund','—']],
   cap:{en:'Intransitive verbs (schlafen, weinen) have no attributive Partizip II: "das geschlafene Kind" does not exist.',
        fa:'فعل‌های ناگذر (schlafen، weinen) اسم مفعول وصفی ندارند: «das geschlafene Kind» وجود ندارد.'}},
  {type:'examples',items:[
   {de:'Das weinende Kind wollte einfach nicht ins Bett.',en:'The crying child simply refused to go to bed.',say:'Das weinende Kind wollte einfach nicht ins Bett.'},
   {de:'Gieß das kochende Wasser langsam über den Tee.',en:'Pour the boiling water slowly over the tea.',say:'Gieß das kochende Wasser langsam über den Tee.'},
   {de:'Ein gekochtes Ei zum Frühstück reicht mir völlig.',en:'A boiled egg for breakfast is quite enough for me.',say:'Ein gekochtes Ei zum Frühstück reicht mir völlig.'},
   {de:'Die steigenden Mieten sind das größte Problem der Stadt.',en:'The rising rents are the city’s biggest problem.',say:'Die steigenden Mieten sind das größte Problem der Stadt.'},
   {de:'Ein gut bezahlter Job ist nicht automatisch ein guter Job.',en:'A well-paid job is not automatically a good job.',say:'Ein gut bezahlter Job ist nicht automatisch ein guter Job.'},
   {de:'Bitte schicken Sie das ausgefüllte Formular bis Montag zurück.',en:'Please send the completed form back by Monday.',say:'Bitte schicken Sie das ausgefüllte Formular bis Montag zurück.'}]},
  {type:'warn',md:{en:'Partizip I is <b>not</b> the English continuous. „I am reading“ is „Ich <b>lese</b>“ — never „<s>Ich bin lesend</s>“ ✗. Partizip I only works in front of a noun (das lesende Kind) or as an adverb (lachend ging er weg).<br>Second trap: the ending. In front of a noun a participle is an adjective, so it must be declined: „ein <s>lachend</s> Kind“ ✗ → „ein <b>lachendes</b> Kind“ ✓.',
        fa:'Partizip I معادل زمان استمراری انگلیسی <b>نیست</b>. «I am reading» می‌شود «Ich lese» — نه «Ich bin lesend». دام دوم پایانه است: پیش از اسم باید صرف شود: «ein lachendes Kind» ✓.'}},
  {type:'tip',md:{en:'Translation shortcut: <b>-end</b> → "-ing", <b>ge…t / ge…en</b> → "-ed". „die <b>wartenden</b> Fahrgäste“ = the waiting passengers · „die <b>verspätete</b> Bahn“ = the delayed train.',
        fa:'میان‌بر ترجمه: <b>-end</b> → «-ing»، <b>ge…t/ge…en</b> → «-ed».'}},
  {type:'quiz',q:{en:'„Vorsicht, das ist ___ Wasser!“ (it is boiling right now)',fa:'«Vorsicht, das ist ___ Wasser!» (همین حالا در حال جوشیدن)'},
   a:'kochendes',o:['gekochtes','kochend','gekocht'],
   ex:{en:'Active and in progress → Partizip I <b>kochend</b> + neuter ending with no article → <b>kochendes</b>. <i>gekochtes</i> would mean already boiled and cooled.',
       fa:'معلوم و در جریان → Partizip I و پایانهٔ خنثی بی حرف تعریف → <b>kochendes</b>.'}}
 ]},

/* ============ 10 · untrennbar ============ */
{id:'untrennbar',ic:'🔒',lv:4,sk:'Verbs',
 title:{en:'Inseparable prefixes',fa:'پیشوندهای جدانشدنی'},
 sub:{en:'be- ge- er- ver- ent- emp- miss- zer-',fa:'be- ge- er- ver- ent- emp- miss- zer-'},
 blocks:[
  {type:'text',md:{en:'You know that <i>aufstehen</i> splits: „Ich <b>stehe</b> um sechs <b>auf</b>.“ A second family of prefixes never splits — and, more surprisingly, refuses the <b>ge-</b> of the Partizip II. Eight of them cover almost everything: <b>be-, ge-, er-, ver-, ent-, emp-, miss-, zer-</b>.',
        fa:'می‌دانی که <i>aufstehen</i> جدا می‌شود. خانوادهٔ دومی از پیشوندها هرگز جدا نمی‌شود — و شگفت‌تر آنکه <b>ge-</b> اسم مفعول را نمی‌پذیرد. هشت پیشوند تقریباً همه را می‌پوشانند: <b>be-، ge-، er-، ver-، ent-، emp-، miss-، zer-</b>.'}},
  {type:'rule',md:{en:'Three facts, all consequences of one thing — these prefixes are <b>unstressed</b>:<br>1. They never separate from the verb, in any tense or clause.<br>2. The Partizip II takes <b>no ge-</b>: besucht, verstanden, erklärt, zerstört.<br>3. With <b>zu</b>, the <i>zu</i> stays in front as a separate word: „zu besuchen“, not „<s>bezusuchen</s>“.',
        fa:'سه نکته، همه نتیجهٔ یک چیز — این پیشوندها <b>بی‌تکیه</b> هستند: ۱) هرگز از فعل جدا نمی‌شوند. ۲) اسم مفعول <b>ge-</b> نمی‌گیرد. ۳) با <b>zu</b>، zu جدا و پیش از فعل می‌ماند.'}},
  {type:'table',head:['Prefix','Verb','Partizip II','Meaning shift'],rows:[
   ['*be-','besuchen','*besucht','makes a verb transitive: sprechen → besprechen'],
   ['*ge-','gehören, gefallen','*gehört, *gefallen','often abstract, with Dativ'],
   ['*er-','erklären, erreichen','*erklärt, *erreicht','getting a result, reaching an end'],
   ['*ver-','verstehen, verlieren','*verstanden, *verloren','away, wrong, or used up'],
   ['*ent-','entscheiden, entschuldigen','*entschieden, *entschuldigt','removing, taking out'],
   ['*emp-','empfehlen, empfangen','*empfohlen, *empfangen','receiving'],
   ['*miss-','missverstehen','*missverstanden','wrongly, badly'],
   ['*zer-','zerstören, zerbrechen','*zerstört, *zerbrochen','to pieces']],
   cap:{en:'Not one ge- in the whole column. The prefix occupies that slot.',
        fa:'در کل این ستون یک ge- هم نیست. پیشوند جای آن را گرفته است.'}},
  {type:'contrast',cols:[
   {t:'separable — prefix stressed',md:{en:'<b>AUF</b>stehen, <b>AN</b>rufen, <b>MIT</b>kommen, <b>EIN</b>kaufen, <b>AUS</b>gehen<br>„Ich <b>rufe</b> dich später <b>an</b>.“<br>Partizip II: an<b>ge</b>rufen (ge- in the middle)<br>With zu: an<b>zu</b>rufen'}},
   {t:'inseparable — stem stressed',md:{en:'be<b>SU</b>chen, ver<b>STE</b>hen, er<b>KLÄ</b>ren, ent<b>SCHEI</b>den<br>„Ich <b>besuche</b> dich später.“<br>Partizip II: besucht (no ge- anywhere)<br>With zu: <b>zu</b> besuchen'}}]},
  {type:'rule',md:{en:'<b>über-, unter-, um-, durch-, wider-</b> can go either way, and the stress tells you which — along with the meaning:<br>• „Der Zug fährt <b>um</b>.“ (separable, literal: it turns back) vs „Wir <b>umfahren</b> die Stadt.“ (inseparable, we drive around it)<br>• „Ich <b>ziehe</b> nächsten Monat <b>um</b>.“ (I move house) vs „Ich <b>umarme</b> dich.“ (I hug you)<br>• „Ich <b>übersetze</b> den Text.“ (I translate — inseparable) vs „Der Fährmann <b>setzt</b> uns <b>über</b>.“ (he ferries us across)<br>Rule of thumb: literal movement → separable; figurative meaning → inseparable.',
        fa:'<b>über-، unter-، um-، durch-</b> می‌توانند هر دو باشند و تکیه آن را مشخص می‌کند: معنای مکانی و واقعی → جداشدنی؛ معنای مجازی → جدانشدنی.'}},
  {type:'examples',items:[
   {de:'Ich habe die Regel endlich verstanden.',en:'I’ve finally understood the rule.',say:'Ich habe die Regel endlich verstanden.'},
   {de:'Die Ärztin hat mir mehr Schlaf empfohlen.',en:'The doctor recommended more sleep to me.',say:'Die Ärztin hat mir mehr Schlaf empfohlen.'},
   {de:'Wir haben uns gestern für die günstigere Wohnung entschieden.',en:'Yesterday we decided on the cheaper flat.',say:'Wir haben uns gestern für die günstigere Wohnung entschieden.'},
   {de:'Der Sturm hat das halbe Dach zerstört.',en:'The storm destroyed half the roof.',say:'Der Sturm hat das halbe Dach zerstört.'},
   {de:'Du hast mich völlig missverstanden.',en:'You’ve completely misunderstood me.',say:'Du hast mich völlig missverstanden.'},
   {de:'Dieses Fahrrad gehört meiner Schwester, nicht mir.',en:'This bike belongs to my sister, not to me.',say:'Dieses Fahrrad gehört meiner Schwester, nicht mir.'}]},
  {type:'warn',md:{en:'The error that shouts "learner": adding <b>ge-</b> anyway. „<s>gebesucht, geverstanden, geerklärt, gezerstört</s>“ ✗ → besucht, verstanden, erklärt, zerstört.<br>The mirror error is splitting them: „<s>Ich stehe das Problem ver</s>“ ✗ → „Ich <b>verstehe</b> das Problem.“<br>Also note: verbs in <b>-ieren</b> take no ge- either — studiert, telefoniert, passiert, reserviert.',
        fa:'خطایی که فریاد «زبان‌آموز» می‌زند: افزودن <b>ge-</b>. «gebesucht، geverstanden» ✗. خطای آینه‌ای جدا کردن آن‌هاست. همچنین فعل‌های <b>-ieren</b> هم ge- نمی‌گیرند: studiert، telefoniert.'}},
  {type:'tip',md:{en:'Say the verb out loud. If your voice goes up on the <i>prefix</i>, it separates. If it goes up on the <i>stem</i>, it does not. Your ear will be right more often than your memory.',
        fa:'فعل را بلند بگو. اگر تکیه روی <i>پیشوند</i> بیفتد، جدا می‌شود؛ اگر روی <i>بن</i> بیفتد، نه. گوشت بیشتر از حافظه‌ات درست می‌گوید.'}},
  {type:'quiz',q:{en:'„Er hat die Aufgabe nicht ___ .“ (verstehen)',fa:'«Er hat die Aufgabe nicht ___ .» (verstehen)'},
   a:'verstanden',o:['geverstanden','verstehen','verstandet'],
   ex:{en:'<b>ver-</b> is inseparable and unstressed, so the Partizip II gets no ge-: <b>verstanden</b>.',
       fa:'<b>ver-</b> جدانشدنی و بی‌تکیه است، پس اسم مفعول ge- نمی‌گیرد: <b>verstanden</b>.'}}
 ]},

/* ============ 11 · verbvalenz ============ */
{id:'verbvalenz',ic:'🧩',lv:4,sk:'Cases',
 title:{en:'How many objects does a verb take?',fa:'یک فعل چند مفعول می‌گیرد؟'},
 sub:{en:'Verb valency — and how to look it up',fa:'ظرفیت فعل — و شیوهٔ یافتنش در فرهنگ لغت'},
 blocks:[
  {type:'text',md:{en:'Learning the four cases is only half the job. The other half is knowing <i>which case a particular verb demands</i> — because the verb, not the meaning, decides. Every German verb comes with a fixed number of empty slots, and filling them with the wrong case is the most common B1 error of all.',
        fa:'یادگیری چهار حالت تنها نیمی از کار است. نیم دیگر دانستن <i>آن حالتی است که فعل معیّن می‌طلبد</i> — چون فعل تصمیم می‌گیرد، نه معنا. هر فعل آلمانی تعداد ثابتی جای خالی دارد و پر کردن آن‌ها با حالت نادرست رایج‌ترین خطای B1 است.'}},
  {type:'table',head:['Pattern','Typical verbs','Example'],rows:[
   ['Nominativ only','schlafen, arbeiten, bleiben, passieren','Das Kind *schläft.'],
   ['Nom + *Akkusativ','sehen, kaufen, brauchen, verstehen, lesen','Ich brauche *einen Rat.'],
   ['Nom + *Dativ','helfen, danken, gefallen, gehören, passen, folgen, antworten, zuhören','Ich helfe *dir.'],
   ['Nom + *Dativ + *Akkusativ','geben, schenken, zeigen, erklären, empfehlen, schicken','Ich erkläre *dir *die Regel.'],
   ['Nom + prepositional object','warten *auf, denken *an, sich freuen *über, sich interessieren *für','Ich warte *auf eine Antwort.'],
   ['Nom + Nom','sein, werden, bleiben','Er ist *Lehrer.']],
   cap:{en:'Six patterns. Every verb you learn belongs to one of them — note it down with the verb.',
        fa:'شش الگو. هر فعلی که یاد می‌گیری به یکی از آن‌ها تعلق دارد — آن را همراه فعل یادداشت کن.'}},
  {type:'rule',md:{en:'The dictionary tells you the pattern in code:<br>• <b>jmdm.</b> = jemandem → <b>Dativ</b><br>• <b>jmdn.</b> = jemanden → <b>Akkusativ</b><br>• <b>etw.</b> = etwas (a thing; the case is given by the pattern)<br>So „jmdm. etw. erklären“ means: person in Dativ, thing in Akkusativ → „Ich erkläre <b>dem Kunden</b> <b>den Vertrag</b>.“ And „warten auf + A“ tells you the preposition is part of the verb.',
        fa:'فرهنگ لغت الگو را با نشانه می‌دهد: <b>jmdm.</b> = داتیو، <b>jmdn.</b> = آکوزاتیو، <b>etw.</b> = چیزی. پس «jmdm. etw. erklären» یعنی شخص داتیو و چیز آکوزاتیو.'}},
  {type:'steps',items:[
   {en:'Look the verb up and read the little abbreviations before the meaning, not after.',fa:'فعل را جست‌وجو کن و نشانه‌های کوچک پیش از معنا را بخوان.'},
   {en:'Write the verb in your list <i>with</i> its slots: „helfen + <b>D</b>“, „fragen + <b>A</b>“, „warten <b>auf</b> + A“.',fa:'فعل را <i>همراه</i> جای‌هایش در فهرست بنویس: «helfen + D»، «fragen + A».'},
   {en:'Learn a one-sentence example, not the abbreviation alone — „Ich helfe dir“ sticks, „helfen + D“ does not.',fa:'یک جملهٔ نمونه یاد بگیر، نه فقط نشانه را.'},
   {en:'If the verb has a preposition, learn the preposition and its case as part of the word.',fa:'اگر فعل حرف اضافه دارد، حرف اضافه و حالتش را بخشی از واژه بدان.'}]},
  {type:'contrast',cols:[
   {t:'fragen — Akkusativ',md:{en:'„Ich <b>frage dich</b>.“ / „Darf ich <b>Sie</b> etwas fragen?“<br>You ask <i>someone</i>: direct object.'}},
   {t:'antworten — Dativ',md:{en:'„Ich <b>antworte dir</b>.“ / „Warum antwortest du <b>mir</b> nicht?“<br>Same conversation, opposite case. Nothing in the meaning predicts it — the verb simply demands Dativ.'}}]},
  {type:'examples',items:[
   {de:'Dieser Vorschlag gefällt mir überhaupt nicht.',en:'I don’t like this proposal at all.',say:'Dieser Vorschlag gefällt mir überhaupt nicht.'},
   {de:'Ich danke dir für deine Geduld.',en:'Thank you for your patience.',say:'Ich danke dir für deine Geduld.'},
   {de:'Kannst du mir diese Rechnung bitte erklären?',en:'Can you explain this bill to me, please?',say:'Kannst du mir diese Rechnung bitte erklären?'},
   {de:'Wir warten seit zwei Wochen auf eine Antwort.',en:'We’ve been waiting two weeks for an answer.',say:'Wir warten seit zwei Wochen auf eine Antwort.'},
   {de:'Das Auto gehört meinem Bruder, nicht mir.',en:'The car belongs to my brother, not to me.',say:'Das Auto gehört meinem Bruder, nicht mir.'},
   {de:'Ich interessiere mich mehr für Politik als für Sport.',en:'I’m more interested in politics than in sport.',say:'Ich interessiere mich mehr für Politik als für Sport.'}]},
  {type:'warn',md:{en:'A short list of verbs that are plain objects in English but <b>Dativ</b> in German. Learn these eight and most of your case errors disappear:<br><b>helfen, danken, gratulieren, folgen, antworten, zuhören, begegnen, passen</b> (+ <b>gefallen, gehören, schmecken</b>).<br>„<s>Ich helfe ihn</s>“ ✗ → „Ich helfe <b>ihm</b>.“ · „<s>Ich danke dich</s>“ ✗ → „Ich danke <b>dir</b>.“ · „<s>Ich gratuliere dich</s>“ ✗ → „Ich gratuliere <b>dir</b>.“',
        fa:'فهرست کوتاهی از فعل‌هایی که در انگلیسی مفعول مستقیم دارند ولی در آلمانی <b>داتیو</b> می‌گیرند: helfen، danken، gratulieren، folgen، antworten، zuhören، begegnen، passen. «Ich helfe ihm» ✓، نه «Ich helfe ihn».'}},
  {type:'tip',md:{en:'With two objects, the normal order is <b>Dativ before Akkusativ</b> — unless the Akkusativ is a pronoun, then it goes first: „Ich gebe <b>dem Kind</b> <b>das Buch</b>.“ → „Ich gebe <b>es</b> <b>dem Kind</b>.“ Short before long, pronoun before noun.',
        fa:'با دو مفعول، ترتیب معمول <b>داتیو پیش از آکوزاتیو</b> است — مگر آکوزاتیو ضمیر باشد که اول می‌آید: «Ich gebe es dem Kind.»'}},
  {type:'quiz',q:{en:'„Dieses Hemd passt ___ nicht mehr.“',fa:'«Dieses Hemd passt ___ nicht mehr.»'},
   a:'mir',o:['mich','ich','meiner'],
   ex:{en:'<i>passen</i> is a Dativ verb — the shirt "fits to me". Dativ of <i>ich</i> = <b>mir</b>.',
       fa:'<i>passen</i> فعل داتیو است. داتیو <i>ich</i> می‌شود <b>mir</b>.'}}
 ]}
,

/* ============ 12 · negation-stellung ============ */
{id:'negation-stellung',ic:'🚫',lv:4,sk:'Sentences',
 title:{en:'Where does nicht go?',fa:'nicht کجا می‌نشیند؟'},
 sub:{en:'The position rules for negation',fa:'قواعد جایگاه نفی'},
 blocks:[
  {type:'text',md:{en:'Everyone learns <b>nicht</b> in the first month and keeps putting it in the wrong place for years. The reason is that English puts "not" early („I do <b>not</b> like…“) while German pushes it as far <b>right</b> as it can — until it hits something it is not allowed to pass.',
        fa:'همه <b>nicht</b> را در ماه اول یاد می‌گیرند و سال‌ها آن را در جای نادرست می‌گذارند. دلیلش این است که انگلیسی «not» را زود می‌آورد، ولی آلمانی آن را تا جای ممکن به <b>راست</b> می‌راند — تا به چیزی برسد که نمی‌تواند از آن بگذرد.'}},
  {type:'rule',md:{en:'<b>nicht</b> goes as far right as possible, but it must stand <i>before</i>:<br>1. the second verb part — Infinitiv, Partizip II, or a separable prefix: „Ich kann dir <b>nicht helfen</b>.“ / „Ich habe es <b>nicht gesehen</b>.“ / „Sie ruft mich <b>nicht an</b>.“<br>2. a predicate adjective or adverb: „Der Film war <b>nicht gut</b>.“<br>3. a prepositional phrase belonging to the verb: „Ich interessiere mich <b>nicht für Fußball</b>.“<br>4. a place expression: „Wir fahren <b>nicht nach Berlin</b>.“',
        fa:'<b>nicht</b> تا جای ممکن به راست می‌رود، ولی باید <i>پیش از</i> این‌ها بایستد: ۱) بخش دوم فعل (مصدر، اسم مفعول، پیشوند جداشدنی)؛ ۲) صفت یا قید خبری؛ ۳) گروه حرف اضافه‌ای وابسته به فعل؛ ۴) عبارت مکان.'}},
  {type:'table',head:['Sentence','Why nicht sits there'],rows:[
   ['Ich kenne ihn *nicht.','nothing follows the pronoun → nicht goes last'],
   ['Ich habe ihn *nicht gesehen.','before the Partizip II'],
   ['Ich kann ihn *nicht erreichen.','before the Infinitiv'],
   ['Ich rufe ihn *nicht an.','before the separable prefix'],
   ['Der Kaffee ist *nicht heiß.','before the predicate adjective'],
   ['Ich warte *nicht auf ihn.','before the verb’s preposition'],
   ['Er wohnt *nicht in Köln.','before the place expression'],
   ['Ich habe ihm das *nicht gesagt.','pronouns always stand in front of nicht']],
   cap:{en:'Pronouns come before nicht; nouns and phrases usually come after it.',
        fa:'ضمایر پیش از nicht می‌آیند؛ اسم‌ها و گروه‌ها معمولاً پس از آن.'}},
  {type:'contrast',cols:[
   {t:'Satznegation — the whole sentence',md:{en:'„Ich fahre <b>nicht</b> nach Berlin.“<br>I am not going to Berlin at all. <b>nicht</b> stands in its normal position and cancels the statement.'}},
   {t:'Teilnegation — one single part',md:{en:'„<b>Nicht ich</b> fahre nach Berlin, sondern mein Bruder.“<br>„Wir treffen uns <b>nicht am Montag</b>, sondern am Dienstag.“<br><b>nicht</b> jumps directly in front of the word it attacks, and <i>sondern</i> usually gives the correction.'}}]},
  {type:'rule',md:{en:'Nouns are usually negated with <b>kein</b>, not with nicht:<br>• <i>ein</i> + noun → <b>kein</b>: „Ich habe <b>keinen</b> Hund.“<br>• bare noun (no article) → <b>kein</b>: „Ich habe <b>keine</b> Zeit.“ / „Ich trinke <b>keinen</b> Kaffee.“<br>• but a noun with <i>der/die/das</i>, a possessive, or a name keeps <b>nicht</b>: „Das ist <b>nicht</b> mein Problem.“ / „Ich kenne <b>den</b> Film <b>nicht</b>.“',
        fa:'اسم‌ها معمولاً با <b>kein</b> نفی می‌شوند، نه nicht: <i>ein</i> + اسم یا اسم بی حرف تعریف → <b>kein</b>. ولی اسم با der/die/das یا صفت ملکی <b>nicht</b> می‌گیرد.'}},
  {type:'examples',items:[
   {de:'Ich kann dir heute leider nicht helfen.',en:'Unfortunately I can’t help you today.',say:'Ich kann dir heute leider nicht helfen.'},
   {de:'Wir sind letztes Jahr nicht in Urlaub gefahren.',en:'We didn’t go on holiday last year.',say:'Wir sind letztes Jahr nicht in Urlaub gefahren.'},
   {de:'Ich habe keine Lust, darüber zu diskutieren.',en:'I don’t feel like discussing it.',say:'Ich habe keine Lust, darüber zu diskutieren.'},
   {de:'Nicht alle Kollegen waren mit dem Plan einverstanden.',en:'Not all colleagues agreed with the plan.',say:'Nicht alle Kollegen waren mit dem Plan einverstanden.'},
   {de:'Das Paket habe ich noch nicht abgeholt.',en:'I haven’t picked the parcel up yet.',say:'Das Paket habe ich noch nicht abgeholt.'},
   {de:'Es tut mir leid, dass ich dir nicht helfen konnte.',en:'I’m sorry that I couldn’t help you.',say:'Es tut mir leid, dass ich dir nicht helfen konnte.'}]},
  {type:'warn',md:{en:'The three real learner errors:<br>1. English order: „<s>Ich nicht gehe</s>“ ✗ → „Ich <b>gehe nicht</b>.“ German has no „do not“ — nothing stands between subject and verb.<br>2. „<s>Ich habe nicht Zeit</s>“ ✗ → „Ich habe <b>keine</b> Zeit.“ A bare noun takes kein.<br>3. Pronoun after nicht: „<s>Ich kenne nicht ihn</s>“ ✗ → „Ich kenne <b>ihn nicht</b>.“ Unstressed pronouns always come first.',
        fa:'سه خطای واقعی: ۱) ترتیب انگلیسی «Ich nicht gehe» ✗ → «Ich gehe nicht». ۲) «nicht Zeit» ✗ → «keine Zeit». ۳) «nicht ihn» ✗ → «ihn nicht».'}},
  {type:'tip',md:{en:'In a subordinate clause the verb is already at the end, so <b>nicht</b> simply stands directly in front of it: „…, weil ich dich <b>nicht verstehe</b>.“ / „…, dass er <b>nicht mitkommen kann</b>.“ Same rule, just a shorter sentence after it.',
        fa:'در جملهٔ پیرو فعل همین‌طور در آخر است، پس <b>nicht</b> بلافاصله پیش از آن می‌ایستد: «…, weil ich dich nicht verstehe.»'}},
  {type:'quiz',q:{en:'„Sie hat mich gestern ___ .“ (anrufen, negated)',fa:'«Sie hat mich gestern ___ .» (anrufen، منفی)'},
   a:'nicht angerufen',o:['angerufen nicht','nicht anrufen','nicht gerufen an'],
   ex:{en:'<b>nicht</b> must stand before the Partizip II, and the Partizip II of a separable verb keeps ge- in the middle: <b>nicht angerufen</b>.',
       fa:'<b>nicht</b> باید پیش از اسم مفعول بایستد و اسم مفعول فعل جداشدنی ge- را در میان نگه می‌دارد.'}}
 ]},

/* ============ 13 · substantivierung ============ */
{id:'substantivierung',ic:'🏗️',lv:4,sk:'Style',
 title:{en:'Verbs and adjectives as nouns',fa:'فعل و صفت در نقش اسم'},
 sub:{en:'das Lernen · das Beste · etwas Neues',fa:'das Lernen · das Beste · etwas Neues'},
 blocks:[
  {type:'text',md:{en:'German turns other word classes into nouns constantly, and it does so with two very simple moves: capitalise an infinitive, or capitalise an adjective. Once you see the pattern, a whole layer of everyday German opens up — <i>beim Essen, das Beste, etwas Neues, der Deutsche</i>.',
        fa:'آلمانی مدام واژه‌های دیگر را به اسم تبدیل می‌کند، با دو حرکت ساده: مصدر را با حرف بزرگ بنویس، یا صفت را با حرف بزرگ بنویس. با دیدن این الگو، لایه‌ای کامل از آلمانی روزمره باز می‌شود.'}},
  {type:'rule',md:{en:'<b>Infinitive → noun.</b> Capitalise it; the gender is always <b>das</b>; there is no plural:<br>lernen → <b>das Lernen</b> · essen → <b>das Essen</b> · rauchen → <b>das Rauchen</b><br>It behaves like any neuter noun, so it combines with prepositions: <b>beim</b> Kochen, <b>zum</b> Mitnehmen, <b>vor dem</b> Schlafen, <b>nach dem</b> Essen.',
        fa:'<b>مصدر → اسم.</b> با حرف بزرگ بنویس؛ جنس همیشه <b>das</b> است و جمع ندارد: lernen → das Lernen. مثل هر اسم خنثی با حرف اضافه ترکیب می‌شود: beim Kochen، zum Mitnehmen.'}},
  {type:'rule',md:{en:'<b>Adjective → noun.</b> Capitalise it and <i>keep the adjective ending</i> — that is the part learners drop:<br>• after der/die/das: <b>der Deutsche</b>, <b>die Deutsche</b>, <b>die Deutschen</b>, <b>das Beste</b><br>• after ein/eine: <b>ein Deutscher</b>, <b>eine Deutsche</b><br>• after etwas/nichts/viel/wenig: neuter <b>-es</b> → <b>etwas Neues</b>, <b>nichts Besonderes</b>, <b>viel Gutes</b><br>• after alles: <b>-e</b> → <b>alles Gute</b>',
        fa:'<b>صفت → اسم.</b> با حرف بزرگ بنویس و <i>پایانهٔ صفت را نگه دار</i> — همین بخشی است که زبان‌آموزان حذف می‌کنند: der Deutsche، ein Deutscher، etwas Neues، alles Gute.'}},
  {type:'table',head:['In front','Ending','Example'],rows:[
   ['der / die / das','*-e','das Beste, der Kranke, die Arbeitslose'],
   ['die (plural)','*-en','die Deutschen, die Angestellten'],
   ['ein (m) / ein (n)','*-er / *-es','ein Deutscher, ein Neues'],
   ['etwas / nichts / viel / wenig','*-es','etwas Neues, nichts Besonderes, viel Gutes'],
   ['alles','*-e','alles Gute, alles Mögliche'],
   ['Infinitiv (always das)','—','das Lernen, das Rauchen, beim Essen']],
   cap:{en:'The endings are the ordinary adjective endings — nothing new to learn, just not to forget.',
        fa:'این پایانه‌ها همان پایانه‌های معمول صفت‌اند — چیز نویی نیست، فقط فراموش نشود.'}},
  {type:'contrast',cols:[
   {t:'etwas Neues — something new, unspecific',md:{en:'„Hast du <b>etwas Neues</b> gehört?“<br>Indefinite, with no article → neuter <b>-es</b>. Same with <i>nichts Interessantes, viel Gutes, wenig Positives</i>.'}},
   {t:'das Neue — the new thing, specific',md:{en:'„<b>Das Neue</b> an diesem Handy ist die Kamera.“<br>Definite, after <i>das</i> → weak ending <b>-e</b>. Same with <i>das Beste, das Wichtigste, das Einzige</i>.'}}]},
  {type:'examples',items:[
   {de:'Das Lernen fällt mir abends deutlich schwerer.',en:'Studying is clearly harder for me in the evening.',say:'Das Lernen fällt mir abends deutlich schwerer.'},
   {de:'Beim Kochen höre ich immer Podcasts.',en:'When I cook I always listen to podcasts.',say:'Beim Kochen höre ich immer Podcasts.'},
   {de:'Das Beste an dem Kurs war die Lehrerin.',en:'The best thing about the course was the teacher.',say:'Das Beste an dem Kurs war die Lehrerin.'},
   {de:'Hast du etwas Neues von ihm gehört?',en:'Have you heard anything new from him?',say:'Hast du etwas Neues von ihm gehört?'},
   {de:'Rauchen ist im ganzen Gebäude verboten.',en:'Smoking is forbidden in the whole building.',say:'Rauchen ist im ganzen Gebäude verboten.'},
   {de:'Ein Deutscher und eine Französin haben das Projekt geleitet.',en:'A German man and a French woman led the project.',say:'Ein Deutscher und eine Französin haben das Projekt geleitet.'},
   {de:'Ich wünsche dir alles Gute für die Prüfung!',en:'I wish you all the best for the exam!',say:'Ich wünsche dir alles Gute für die Prüfung!'}]},
  {type:'warn',md:{en:'Three traps:<br>1. The ending disappears. „<s>ein Deutsche</s>“ ✗ → „ein <b>Deutscher</b>“ (m) / „eine <b>Deutsche</b>“ (f). „<s>etwas Neue</s>“ ✗ → „etwas <b>Neues</b>“.<br>2. The capital letter disappears. „<s>das lernen</s>“ ✗ — once it is a noun, it is written big.<br>3. Nationality: „Ich bin <b>Deutscher</b>“ (a German, noun) vs „Ich bin <b>deutsch</b>“ (German, adjective — about papers and identity, not profession). Both exist; they are not interchangeable.',
        fa:'سه دام: ۱) حذف پایانه: «ein Deutscher» ✓ نه «ein Deutsche»؛ «etwas Neues» ✓ نه «etwas Neue». ۲) حذف حرف بزرگ: اسم شد، بزرگ نوشته می‌شود. ۳) «Ich bin Deutscher» (اسم) در برابر «Ich bin deutsch» (صفت).'}},
  {type:'tip',md:{en:'A nominalised infinitive after <b>beim / vor dem / nach dem</b> is a compressed time clause: „<b>Beim Lesen</b> schlafe ich ein“ = „<b>Wenn ich lese</b>, schlafe ich ein.“ Handy for short, natural sentences — but do not overdo it, or your German starts to sound like an official form.',
        fa:'مصدرِ اسم‌شده پس از <b>beim / vor dem / nach dem</b> یک جملهٔ زمان فشرده است: «Beim Lesen schlafe ich ein» = «Wenn ich lese, schlafe ich ein». ولی زیاده‌روی نکن.'}},
  {type:'quiz',q:{en:'„Ich habe nichts ___ gefunden.“ (interessant)',fa:'«Ich habe nichts ___ gefunden.» (interessant)'},
   a:'Interessantes',o:['Interessante','interessantes','Interessanten'],
   ex:{en:'After <i>nichts</i> the adjective becomes a neuter noun with the strong ending <b>-es</b>, written with a capital letter: <b>nichts Interessantes</b>.',
       fa:'پس از <i>nichts</i> صفت اسم خنثی می‌شود با پایانهٔ قوی <b>-es</b> و حرف بزرگ.'}}
 ]},

/* ============ 14 · vergleichssaetze ============ */
{id:'vergleichssaetze',ic:'⚖️',lv:4,sk:'Clauses',
 title:{en:'Comparison clauses',fa:'جمله‌های مقایسه'},
 sub:{en:'als · wie · je…desto · als ob · so…dass',fa:'als · wie · je…desto · als ob · so…dass'},
 blocks:[
  {type:'text',md:{en:'Comparing is the heart of arguing, and at B1 you need more than <i>größer als</i>. Five structures cover almost every comparison you will ever write: <b>als</b>, <b>wie</b>, <b>je … desto</b>, <b>als ob</b>, and <b>so … dass</b>.',
        fa:'مقایسه قلب استدلال است و در سطح B1 به چیزی بیش از <i>größer als</i> نیاز داری. پنج ساخت تقریباً همهٔ مقایسه‌ها را می‌پوشاند: <b>als</b>، <b>wie</b>، <b>je … desto</b>، <b>als ob</b> و <b>so … dass</b>.'}},
  {type:'rule',md:{en:'The basic split:<br>• <b>als</b> after a comparative — things are <i>unequal</i>: „Die Miete ist <b>höher als</b> in meiner alten Stadt.“<br>• <b>wie</b> after <i>so / genauso / fast so</i> — things are <i>equal</i>: „Mein Bruder ist <b>genauso faul wie</b> ich.“<br>Comparative → als. Equality → wie. There is no third option.',
        fa:'تقسیم اصلی: <b>als</b> پس از صفت برتر — نابرابری؛ <b>wie</b> پس از so/genauso — برابری. گزینهٔ سومی وجود ندارد.'}},
  {type:'rule',md:{en:'<b>je … desto</b> (or <b>je … umso</b>) links two things that grow together. Both halves need a comparative, and the word order flips:<br>„<b>Je länger</b> ich darüber <b>nachdenke</b>, <b>desto unsicherer werde</b> ich.“<br>• <b>je</b>-part = subordinate clause → verb at the <b>end</b><br>• <b>desto</b>-part = main clause → comparative first, then the <b>verb in second position</b>, then the subject',
        fa:'<b>je … desto</b> دو چیز را که با هم رشد می‌کنند پیوند می‌دهد. هر دو بخش به صفت برتر نیاز دارند: بخش <b>je</b> جملهٔ پیرو است (فعل در آخر) و بخش <b>desto</b> جملهٔ اصلی (صفت برتر، سپس فعل در جایگاه دوم).'}},
  {type:'table',head:['Structure','Meaning','Example'],rows:[
   ['Komparativ + *als','unequal','Die Miete ist höher *als früher.'],
   ['(genau)so + *wie','equal','Er arbeitet so viel *wie ich.'],
   ['*je … desto','parallel growth','*Je mehr man übt, *desto leichter wird es.'],
   ['*als ob / *als wenn','unreal comparison (+ Konjunktiv II)','Er redet, *als ob er der Chef wäre.'],
   ['*so … dass','degree in the main clause','Es war *so kalt, *dass wir zu Hause blieben.'],
   ['*sodass','consequence, one word','Der Zug hatte Verspätung, *sodass wir den Anschluss verpassten.']],
   cap:{en:'Note the last two: if "so" is already in the main clause, the clause starts with dass alone.',
        fa:'به دو ردیف آخر دقت کن: اگر «so» در جملهٔ اصلی باشد، جملهٔ پیرو تنها با dass آغاز می‌شود.'}},
  {type:'contrast',cols:[
   {t:'so … dass — I set the degree',md:{en:'„Der Vortrag war <b>so</b> langweilig, <b>dass</b> die Hälfte gegangen ist.“<br><b>so</b> sits in front of the adjective in the main clause and announces the consequence. The clause begins with <b>dass</b>.'}},
   {t:'sodass — I just add the consequence',md:{en:'„Der Vortrag war sehr langweilig, <b>sodass</b> die Hälfte gegangen ist.“<br>No <i>so</i> in the main clause; the single word <b>sodass</b> carries the whole link. Both sentences mean the same.'}}]},
  {type:'rule',md:{en:'<b>als ob</b> compares with something unreal, so it takes <b>Konjunktiv II</b>: „Sie tut, <b>als ob</b> sie nichts <b>wüsste</b>.“<br>You may also drop <i>ob</i> — and then the verb jumps straight after <b>als</b>: „Sie tut, <b>als wüsste</b> sie nichts.“ Same meaning, slightly more elegant.',
        fa:'<b>als ob</b> با چیزی غیرواقعی مقایسه می‌کند، پس <b>وجه شرطی</b> می‌گیرد. می‌توانی <i>ob</i> را حذف کنی و آن‌گاه فعل بلافاصله پس از <b>als</b> می‌آید: «als wüsste sie nichts».'}},
  {type:'examples',items:[
   {de:'Die Mieten sind hier deutlich höher als in meiner alten Stadt.',en:'Rents here are clearly higher than in my old city.',say:'Die Mieten sind hier deutlich höher als in meiner alten Stadt.'},
   {de:'Der Kurs war genauso anstrengend wie die Arbeit selbst.',en:'The course was just as exhausting as the job itself.',say:'Der Kurs war genauso anstrengend wie die Arbeit selbst.'},
   {de:'Je länger die Sitzung dauerte, desto nervöser wurden alle.',en:'The longer the meeting lasted, the more nervous everyone got.',say:'Je länger die Sitzung dauerte, desto nervöser wurden alle.'},
   {de:'Er redet immer, als ob er alles besser wüsste.',en:'He always talks as if he knew everything better.',say:'Er redet immer, als ob er alles besser wüsste.'},
   {de:'Das Essen war so salzig, dass ich es nicht essen konnte.',en:'The food was so salty that I couldn’t eat it.',say:'Das Essen war so salzig, dass ich es nicht essen konnte.'},
   {de:'Der Bus kam zwanzig Minuten zu spät, sodass wir den Film verpasst haben.',en:'The bus came twenty minutes late, so that we missed the film.',say:'Der Bus kam zwanzig Minuten zu spät, sodass wir den Film verpasst haben.'}]},
  {type:'warn',md:{en:'„größer <s>wie</s>“ ✗ — you will hear this from native speakers in some regions, and it is still marked wrong in every exam. Comparative always takes <b>als</b>: „größer <b>als</b>“, „besser <b>als</b>“, „mehr <b>als</b>“.<br>The mirror error: „so groß <s>als</s>“ ✗ → „so groß <b>wie</b>“. And „<s>als wie</s>“ ✗ exists in neither direction.',
        fa:'«größer wie» ✗ — در برخی مناطق شنیده می‌شود ولی در هر آزمونی غلط است. صفت برتر همیشه <b>als</b> می‌گیرد. خطای آینه‌ای: «so groß als» ✗ → «so groß wie».'}},
  {type:'quiz',q:{en:'„Je mehr ich lese, ___ besser schreibe ich.“',fa:'«Je mehr ich lese, ___ besser schreibe ich.»'},
   a:'desto',o:['je','als','wie'],
   ex:{en:'The partner of <b>je</b> is <b>desto</b> (or <i>umso</i>), followed by the comparative and then the verb in second position.',
       fa:'همراه <b>je</b> واژهٔ <b>desto</b> (یا umso) است، سپس صفت برتر و فعل در جایگاه دوم.'}}
 ]},

/* ============ 15 · modalpartikel-basis ============ */
{id:'modalpartikel-basis',ic:'🎚️',lv:4,sk:'Style',
 title:{en:'Modal particles: doch, mal, ja, denn, eben',fa:'ذرات وجهی: doch، mal، ja، denn، eben'},
 sub:{en:'The little words that carry attitude',fa:'واژه‌های کوچکی که لحن را می‌سازند'},
 blocks:[
  {type:'text',md:{en:'„Komm mit!“ is an order. „Komm <b>doch</b> mit!“ is an invitation. Nothing changed in the information — only the attitude. These tiny words are called <b>Modalpartikeln</b>, and they are the single clearest difference between correct German and German that sounds like a human being.',
        fa:'«Komm mit!» دستور است. «Komm doch mit!» دعوت است. هیچ اطلاعاتی عوض نشد — تنها لحن. این واژه‌های کوچک <b>ذرات وجهی</b> نام دارند و روشن‌ترین تفاوت میان آلمانیِ درست و آلمانیِ طبیعی‌اند.'}},
  {type:'table',head:['Particle','What it adds','Example'],rows:[
   ['*doch','you already know this / come on, do it','Das habe ich dir *doch gesagt! · Komm *doch mit!'],
   ['*mal','casual, "just", takes the weight out of a request','Kannst du mir *mal helfen? · Warte *mal!'],
   ['*ja','we both know this — shared knowledge','Du weißt *ja, wie er ist.'],
   ['*denn','interest, warmth — only in questions','Wo bist du *denn? · Wie heißt du *denn?'],
   ['*eben','that is simply how it is — resignation','Das ist *eben so. · Dann müssen wir *eben warten.']],
   cap:{en:'None of them can be translated word for word. Learn them in whole sentences.',
        fa:'هیچ‌کدام واژه‌به‌واژه ترجمه نمی‌شوند. آن‌ها را در جمله‌های کامل یاد بگیر.'}},
  {type:'rule',md:{en:'Position: a modal particle lives in the <b>middle field</b> — after the conjugated verb and after the pronouns, before the new information:<br>„Gib <b>mir mal</b> das Buch.“ (verb – pronoun – particle – new info)<br>„Kannst du <b>mir mal</b> helfen?“<br>They can never take position 1, and they never carry stress. Two of them can stack, in a fixed order: „Probier es <b>doch mal</b>!“ — never „mal doch“.',
        fa:'جایگاه: ذرهٔ وجهی در <b>میانهٔ جمله</b> است — پس از فعل صرف‌شده و پس از ضمایر، پیش از اطلاع نو: «Gib mir mal das Buch.» هرگز جایگاه ۱ را نمی‌گیرند و هرگز تکیه ندارند. ترتیب ثابت است: «doch mal»، نه «mal doch».'}},
  {type:'dialog',lines:[
   {who:'A',de:'Wo warst du denn so lange?',en:'Where on earth were you all this time?'},
   {who:'B',de:'Ich habe dir ja gesagt, dass es länger dauert.',en:'I did tell you it would take longer.'},
   {who:'A',de:'Dann ruf doch mal an, wenn du dich verspätest.',en:'Then do give me a call when you’re running late.'},
   {who:'B',de:'Ist ja gut. Ich habe es eben vergessen.',en:'All right, all right. I just forgot.'},
   {who:'A',de:'Komm, setz dich erst mal hin.',en:'Come on, sit down first.'}]},
  {type:'examples',items:[
   {de:'Das habe ich dir doch letzte Woche erklärt!',en:'But I explained that to you last week!',say:'Das habe ich dir doch letzte Woche erklärt!'},
   {de:'Ruf mich mal an, wenn du Zeit hast.',en:'Give me a call sometime when you have time.',say:'Ruf mich mal an, wenn du Zeit hast.'},
   {de:'Du kennst ihn ja besser als ich.',en:'You know him better than I do, after all.',say:'Du kennst ihn ja besser als ich.'},
   {de:'Warum hast du denn nichts gesagt?',en:'Why didn’t you say anything, then?',say:'Warum hast du denn nichts gesagt?'},
   {de:'Ich kann es nicht ändern — es ist eben so.',en:'I can’t change it — that’s just how it is.',say:'Ich kann es nicht ändern — es ist eben so.'},
   {de:'Probier es doch mal mit weniger Zucker.',en:'Why not try it with less sugar.',say:'Probier es doch mal mit weniger Zucker.'}]},
  {type:'warn',md:{en:'Three things to watch:<br>1. <b>denn</b> as a particle only lives in <i>questions</i>: „Wo bist du <b>denn</b>?“ ✓ — „Ich bin <s>denn</s> müde“ ✗. (The <b>denn</b> that means "because" is a different word, and it stands between two clauses.)<br>2. An <b>unstressed</b> particle softens; a <b>stressed</b> one is a different word entirely. „Komm doch mit“ (friendly) vs „<b>DOCH!</b>“ (= yes it is! — contradicting a negative question).<br>3. Do not translate them one by one. „mal“ here is not "times", „ja“ here is not "yes".',
        fa:'سه نکته: ۱) <b>denn</b> به عنوان ذره تنها در <i>پرسش</i> می‌آید. ۲) ذرهٔ <b>بی‌تکیه</b> نرم می‌کند؛ با تکیه واژهٔ دیگری است («DOCH!» = بله که هست). ۳) آن‌ها را واژه‌به‌واژه ترجمه نکن: اینجا «mal» یعنی «بار» نیست و «ja» یعنی «بله» نیست.'}},
  {type:'tip',md:{en:'Leaving the particles out is never grammatically wrong — it just sounds flat or abrupt. Start with two: <b>mal</b> in requests („Kannst du mir mal helfen?“) and <b>denn</b> in questions („Was machst du denn?“). Those two alone move you noticeably closer to natural speech.',
        fa:'حذف ذرات هیچ‌گاه غلط دستوری نیست — فقط خشک یا تند به گوش می‌رسد. با دو تا شروع کن: <b>mal</b> در درخواست و <b>denn</b> در پرسش.'}},
  {type:'quiz',q:{en:'„Wie heißt du ___ ?“ (friendly interest)',fa:'«Wie heißt du ___ ?» (با علاقهٔ دوستانه)'},
   a:'denn',o:['ja','eben','mal'],
   ex:{en:'In a question, warm interest is carried by <b>denn</b>. <i>ja</i> and <i>eben</i> cannot stand in a question like this at all.',
       fa:'در پرسش، علاقهٔ دوستانه با <b>denn</b> بیان می‌شود. <i>ja</i> و <i>eben</i> در چنین پرسشی نمی‌آیند.'}}
 ]},

/* ============ 16 · textkohaesion ============ */
{id:'textkohaesion',ic:'🧵',lv:4,sk:'Style',
 title:{en:'Linking sentences into a text',fa:'پیوند جمله‌ها در یک متن'},
 sub:{en:'Pronouns, da-words, adverbs, given before new',fa:'ضمایر، واژه‌های da، قیدها، کهنه پیش از نو'},
 blocks:[
  {type:'text',md:{en:'At B1 your sentences are correct — and your texts still read like a list. The reason is almost never grammar. It is that each sentence starts from zero instead of <b>picking something up</b> from the one before it. A text is a chain, and German gives you four kinds of link.',
        fa:'در سطح B1 جمله‌هایت درست‌اند — و متن‌هایت هنوز مثل فهرست خوانده می‌شوند. دلیلش تقریباً هیچ‌گاه دستور نیست؛ این است که هر جمله از صفر آغاز می‌شود به‌جای آنکه چیزی را از جملهٔ پیشین <b>بردارد</b>. متن یک زنجیر است و آلمانی چهار نوع حلقه می‌دهد.'}},
  {type:'table',head:['Link','How it works','Example'],rows:[
   ['Pronoun','replaces a noun already mentioned','Ich habe einen Kollegen. *Er kommt aus Polen.'],
   ['Demonstrative das / dieser','points back at the whole idea','Wir haben über Mieten gesprochen. *Das war ein schwieriges Thema.'],
   ['da-compound','replaces preposition + thing','Wir haben über das Projekt geredet. *Darüber möchte ich noch nachdenken.'],
   ['Adverb','names the relation: time, reason, contrast','*Deshalb · *Danach · *Außerdem · *Allerdings · *Trotzdem · *Dann']],
   cap:{en:'All four put the known information at the front — which is exactly where German wants it.',
        fa:'هر چهار، اطلاع شناخته‌شده را در آغاز می‌گذارند — همان‌جا که آلمانی می‌خواهد.'}},
  {type:'rule',md:{en:'<b>Given before new.</b> Position 1 belongs to what the reader already knows; the new, important information goes to the <b>end</b> of the sentence. That is why German puts link words in position 1 so often — and why the verb then slides into position 2:<br>„Die Wohnung ist schön. <b>Allerdings</b> ist sie zu teuer.“<br>„Ich habe keinen Führerschein. <b>Deshalb</b> fahre ich immer Rad.“',
        fa:'<b>کهنه پیش از نو.</b> جایگاه ۱ از آنِ چیزی است که خواننده می‌داند؛ اطلاع نو و مهم به <b>پایان</b> جمله می‌رود. از همین رو واژه‌های پیوند اغلب در جایگاه ۱ می‌آیند و فعل به جایگاه ۲ می‌رود.'}},
  {type:'contrast',cols:[
   {t:'Without links — a list',md:{en:'„Ich habe eine Wohnung gesehen. Die Wohnung liegt am Park. Die Wohnung ist günstig. Das Bad ist klein. Ich überlege noch.“<br>Every sentence correct. Every sentence starting again from nothing.'}},
   {t:'With links — a text',md:{en:'„Ich habe eine Wohnung gesehen. <b>Sie</b> liegt am Park und ist überraschend günstig. <b>Allerdings</b> ist das Bad sehr klein. <b>Deshalb</b> überlege ich noch.“<br>Same facts, half the words, and a reader who never loses the thread.'}}]},
  {type:'steps',items:[
   {en:'Read your text and underline the first word of every sentence.',fa:'متن را بخوان و واژهٔ نخست هر جمله را خط بکش.'},
   {en:'If three sentences start with <i>Ich</i>, you have found the problem.',fa:'اگر سه جمله با <i>Ich</i> آغاز شوند، مشکل را یافته‌ای.'},
   {en:'Replace repeated nouns with pronouns or demonstratives.',fa:'اسم‌های تکرارشده را با ضمیر یا اشاره عوض کن.'},
   {en:'Put a link word in position 1 — and remember the verb then comes second.',fa:'یک واژهٔ پیوند در جایگاه ۱ بگذار — و یادت باشد فعل سپس دوم می‌آید.'},
   {en:'Move the new information to the end of the sentence.',fa:'اطلاع نو را به پایان جمله ببر.'}]},
  {type:'examples',items:[
   {de:'Letzte Woche habe ich eine neue Wohnung gesehen.',en:'Last week I saw a new flat.',say:'Letzte Woche habe ich eine neue Wohnung gesehen.'},
   {de:'Sie liegt direkt am Park und ist überraschend günstig.',en:'It’s right by the park and surprisingly cheap.',say:'Sie liegt direkt am Park und ist überraschend günstig.'},
   {de:'Allerdings ist das Badezimmer sehr klein.',en:'The bathroom, however, is very small.',say:'Allerdings ist das Badezimmer sehr klein.'},
   {de:'Außerdem müsste ich alle Zimmer neu streichen.',en:'Besides, I’d have to repaint every room.',say:'Außerdem müsste ich alle Zimmer neu streichen.'},
   {de:'Darüber möchte ich erst mit dem Vermieter sprechen.',en:'I’d like to talk to the landlord about that first.',say:'Darüber möchte ich erst mit dem Vermieter sprechen.'},
   {de:'Trotzdem habe ich ein gutes Gefühl.',en:'All the same, I have a good feeling about it.',say:'Trotzdem habe ich ein gutes Gefühl.'}]},
  {type:'warn',md:{en:'Four things that break the chain:<br>1. Pronouns follow <b>German</b> gender, not natural gender: „Das Mädchen ist krank. <b>Es</b> bleibt zu Hause.“ — <i>das Mädchen</i> → <b>es</b>.<br>2. <b>dann</b> (then) is not <b>denn</b> (because). „Erst esse ich, <b>dann</b> lerne ich.“<br>3. A link word in position 1 pushes the verb to position 2: „<s>Deshalb ich fahre Rad</s>“ ✗ → „Deshalb <b>fahre</b> ich Rad.“<br>4. Do not open a pronoun chain the reader cannot follow. If two things could be „es“, repeat the noun.',
        fa:'چهار چیز که زنجیر را می‌شکند: ۱) ضمیر از جنس <b>دستوری</b> پیروی می‌کند، نه طبیعی: das Mädchen → <b>es</b>. ۲) <b>dann</b> («سپس») با <b>denn</b> («چون») یکی نیست. ۳) واژهٔ پیوند در جایگاه ۱ فعل را به جایگاه ۲ می‌راند. ۴) زنجیرهٔ ضمیری مبهم نساز.'}},
  {type:'tip',md:{en:'Keep a small stock of link words ready and you will never stall in the writing exam: <b>zuerst – dann – danach – außerdem – deshalb – allerdings – trotzdem – zum Schluss</b>. Four of them in a 150-word text is plenty.',
        fa:'ذخیرهٔ کوچکی از واژه‌های پیوند آماده داشته باش: <b>zuerst – dann – danach – außerdem – deshalb – allerdings – trotzdem – zum Schluss</b>. چهار تا در متنی ۱۵۰ واژه‌ای کافی است.'}},
  {type:'quiz',q:{en:'„Die Wohnung ist wirklich schön. ___ ist sie mir zu teuer.“',fa:'«Die Wohnung ist wirklich schön. ___ ist sie mir zu teuer.»'},
   a:'Allerdings',o:['Deshalb','Danach','Außerdem'],
   ex:{en:'The second sentence contradicts the praise, so you need a contrast link: <b>Allerdings</b>. <i>Deshalb</i> would claim a reason, <i>außerdem</i> would add a second plus point.',
       fa:'جملهٔ دوم با ستایش جملهٔ اول در تضاد است، پس واژهٔ پیوندِ تضاد لازم است: <b>Allerdings</b>.'}}
 ]}
];

/* ===================== DRILLS ===================== */
window.DRILL_B1=[

/* --- temporalsaetze --- */
{gid:'temporalsaetze',lv:4,sk:'Clauses',
 s:'___ ich klein war, wohnte ich in Hamburg.',a:'Als',o:['Wenn','Wann','Ob'],
 ex:'One single period in the past → als. Wenn would mean "every time I was small".',
 tr:'When I was little, I lived in Hamburg.',say:'Als ich klein war, wohnte ich in Hamburg.'},
{gid:'temporalsaetze',lv:4,sk:'Clauses',
 s:'___ ich Zeit habe, gehe ich schwimmen.',a:'Wenn',o:['Als','Wann','Wie'],
 ex:'Present tense and repeated → wenn. Als is only for a single event in the past.',
 tr:'When(ever) I have time, I go swimming.',say:'Wenn ich Zeit habe, gehe ich schwimmen.'},
{gid:'temporalsaetze',lv:4,sk:'Clauses',
 s:'Ich weiß nicht, ___ der Bus kommt.',a:'wann',o:['wenn','als','wie'],
 ex:'An indirect question about a time → wann. This is where English "when" misleads you.',
 tr:'I don’t know when the bus is coming.',say:'Ich weiß nicht, wann der Bus kommt.'},
{gid:'temporalsaetze',lv:4,sk:'Clauses',
 s:'___ du den Vertrag unterschreibst, lies ihn noch einmal.',a:'Bevor',o:['Nachdem','Seitdem','Sobald'],
 ex:'Reading comes first, signing after → bevor. Both clauses stay in the same tense.',
 tr:'Before you sign the contract, read it once more.',say:'Bevor du den Vertrag unterschreibst, lies ihn noch einmal.'},
{gid:'temporalsaetze',lv:4,sk:'Clauses',
 s:'___ ich mehr lese, fällt mir das Schreiben leichter.',a:'Seitdem',o:['Nachdem','Bevor','Während'],
 ex:'A starting point in the past with an effect that still lasts → seitdem + Präsens.',
 tr:'Since I’ve been reading more, writing has got easier for me.',say:'Seitdem ich mehr lese, fällt mir das Schreiben leichter.'},
{gid:'temporalsaetze',lv:4,sk:'Clauses',
 s:'Ich bleibe hier, ___ du zurückkommst.',a:'bis',o:['seitdem','bevor','während'],
 ex:'bis marks the end point of the waiting. Präsens is used for that future moment.',
 tr:'I’ll stay here until you come back.',say:'Ich bleibe hier, bis du zurückkommst.'},
{gid:'temporalsaetze',lv:4,sk:'Clauses',
 s:'Nachdem er die Stelle verloren ___, zog er zurück zu seinen Eltern.',a:'hatte',o:['hat','war','hätte'],
 ex:'nachdem forces a tense step back: Plusquamperfekt (hatte verloren) with a Präteritum main clause.',
 tr:'After he had lost his job, he moved back in with his parents.',say:'Nachdem er die Stelle verloren hatte, zog er zurück zu seinen Eltern.'},
{gid:'temporalsaetze',lv:4,sk:'Clauses',
 s:'Immer wenn meine Großmutter uns besuchte, ___ sie uns Geschichten.',a:'erzählte',o:['erzählt','hat erzählt','erzählen'],
 ex:'The time clause fills position 1, so the main verb comes straight after the comma — Präteritum here: erzählte.',
 tr:'Whenever my grandmother visited us, she told us stories.',say:'Immer wenn meine Großmutter uns besuchte, erzählte sie uns Geschichten.'},

/* --- kausal-konzessiv --- */
{gid:'kausal-konzessiv',lv:4,sk:'Connectors',
 s:'Ich bleibe heute zu Hause, ___ ich krank bin.',a:'weil',o:['denn','trotzdem','deshalb'],
 ex:'The verb bin is at the end, so the connector must be subordinating → weil. With denn you would say: denn ich bin krank.',
 tr:'I’m staying at home today because I’m ill.',say:'Ich bleibe heute zu Hause, weil ich krank bin.'},
{gid:'kausal-konzessiv',lv:4,sk:'Connectors',
 s:'Ich bleibe heute zu Hause, ___ ich bin krank.',a:'denn',o:['weil','obwohl','trotzdem'],
 ex:'Normal word order (ich bin) after the comma → only denn works. weil/obwohl would send bin to the end.',
 tr:'I’m staying at home today, for I’m ill.',say:'Ich bleibe heute zu Hause, denn ich bin krank.'},
{gid:'kausal-konzessiv',lv:4,sk:'Connectors',
 s:'___ ich sehr müde war, habe ich weitergearbeitet.',a:'Obwohl',o:['Trotzdem','Weil','Denn'],
 ex:'Concession with the verb at the end → obwohl. trotzdem is an adverb and cannot introduce a clause.',
 tr:'Although I was very tired, I kept working.',say:'Obwohl ich sehr müde war, habe ich weitergearbeitet.'},
{gid:'kausal-konzessiv',lv:4,sk:'Connectors',
 s:'Das Angebot ist gut. ___ nehme ich es nicht.',a:'Trotzdem',o:['Obwohl','Weil','Denn'],
 ex:'Two separate sentences and inversion (nehme ich) → an adverb in position 1: Trotzdem.',
 tr:'The offer is good. All the same I’m not taking it.',say:'Das Angebot ist gut. Trotzdem nehme ich es nicht.'},
{gid:'kausal-konzessiv',lv:4,sk:'Connectors',
 s:'Wir haben das Spiel verloren, ___ wir viel besser gespielt haben.',a:'obwohl',o:['weil','denn','deshalb'],
 ex:'Playing better is no reason for losing — it contradicts it. Concession + verb last → obwohl.',
 tr:'We lost the match although we played much better.',say:'Wir haben das Spiel verloren, obwohl wir viel besser gespielt haben.'},
{gid:'kausal-konzessiv',lv:4,sk:'Connectors',
 s:'Es hat geregnet. ___ haben wir im Garten gegessen.',a:'Trotzdem',o:['Obwohl','Denn','Weil'],
 ex:'Position 1 is taken by the adverb, so the verb haben comes second and the subject wir follows it.',
 tr:'It rained. We ate in the garden anyway.',say:'Es hat geregnet. Trotzdem haben wir im Garten gegessen.'},
{gid:'kausal-konzessiv',lv:4,sk:'Connectors',
 s:'Sie lernt jeden Tag Vokabeln, ___ sie in Wien studieren will.',a:'weil',o:['denn','trotzdem','obwohl'],
 ex:'Reason, and the modal will sits at the end → weil. denn would need: denn sie will in Wien studieren.',
 tr:'She learns vocabulary every day because she wants to study in Vienna.',say:'Sie lernt jeden Tag Vokabeln, weil sie in Wien studieren will.'},
{gid:'kausal-konzessiv',lv:4,sk:'Connectors',
 s:'Er ist zu spät gekommen, ___ er den Bus verpasst hat.',a:'weil',o:['denn','trotzdem','obwohl'],
 ex:'Reason in the Perfekt: the auxiliary hat goes to the very end of the weil-clause.',
 tr:'He arrived late because he had missed the bus.',say:'Er ist zu spät gekommen, weil er den Bus verpasst hat.'},
{gid:'kausal-konzessiv',lv:4,sk:'Connectors',
 s:'Obwohl der Zug billiger ___, fahren die meisten mit dem Auto.',a:'ist',o:['ist es','es ist','sei'],
 ex:'obwohl sends the conjugated verb to the end of its clause — and the main clause then starts with the verb fahren.',
 tr:'Although the train is cheaper, most people drive.',say:'Obwohl der Zug billiger ist, fahren die meisten mit dem Auto.'},

/* --- finalsaetze --- */
{gid:'finalsaetze',lv:4,sk:'Clauses',
 s:'Ich lerne jeden Tag, ___ die Prüfung zu bestehen.',a:'um',o:['damit','für','dass'],
 ex:'Same subject in both halves (I learn, I pass) → um … zu.',
 tr:'I study every day in order to pass the exam.',say:'Ich lerne jeden Tag, um die Prüfung zu bestehen.'},
{gid:'finalsaetze',lv:4,sk:'Clauses',
 s:'Ich spreche langsam, ___ du mich besser verstehst.',a:'damit',o:['um','um zu','für'],
 ex:'The second half has its own subject (du), so um … zu is impossible → damit.',
 tr:'I speak slowly so that you understand me better.',say:'Ich spreche langsam, damit du mich besser verstehst.'},
{gid:'finalsaetze',lv:4,sk:'Clauses',
 s:'Sie fährt in die Stadt, um neue Schuhe ___ kaufen.',a:'zu',o:['zum','um','für'],
 ex:'um … zu is a frame: um at the start, zu + Infinitiv at the end.',
 tr:'She’s going into town to buy new shoes.',say:'Sie fährt in die Stadt, um neue Schuhe zu kaufen.'},
{gid:'finalsaetze',lv:4,sk:'Clauses',
 s:'Sie ruft an, um den Termin ___.',a:'abzusagen',o:['zu absagen','absagen zu','abgesagt zu'],
 ex:'With a separable verb, zu goes inside the word: ab + zu + sagen → abzusagen.',
 tr:'She’s calling to cancel the appointment.',say:'Sie ruft an, um den Termin abzusagen.'},
{gid:'finalsaetze',lv:4,sk:'Clauses',
 s:'___ seine Eltern sich keine Sorgen machen, schreibt er jeden Tag.',a:'Damit',o:['Um','Um zu','Dafür'],
 ex:'Different subjects (the parents worry, he writes) → damit, with the verb at the end of its clause.',
 tr:'So that his parents don’t worry, he writes every day.',say:'Damit seine Eltern sich keine Sorgen machen, schreibt er jeden Tag.'},
{gid:'finalsaetze',lv:4,sk:'Clauses',
 s:'Die Stadt baut Radwege, ___ weniger Leute mit dem Auto fahren.',a:'damit',o:['um','um zu','sodass'],
 ex:'A new subject appears (weniger Leute), so you need a full clause with damit.',
 tr:'The city is building cycle paths so that fewer people drive.',say:'Die Stadt baut Radwege, damit weniger Leute mit dem Auto fahren.'},
{gid:'finalsaetze',lv:4,sk:'Clauses',
 s:'Ich habe ein Wörterbuch gekauft, um die Zeitung lesen zu ___.',a:'können',o:['kann','könnte','gekonnt'],
 ex:'A modal in an um…zu clause stays in the infinitive and goes last: lesen zu können.',
 tr:'I bought a dictionary in order to be able to read the newspaper.',say:'Ich habe ein Wörterbuch gekauft, um die Zeitung lesen zu können.'},
{gid:'finalsaetze',lv:4,sk:'Clauses',
 s:'Damit ich nicht zu spät ___, nehme ich den früheren Zug.',a:'komme',o:['kommen','zu kommen','gekommen'],
 ex:'damit introduces a real clause: the conjugated verb komme stands at the end, and the main verb nehme follows the comma.',
 tr:'So that I’m not too late, I’ll take the earlier train.',say:'Damit ich nicht zu spät komme, nehme ich den früheren Zug.'},

/* --- konditional --- */
{gid:'konditional',lv:4,sk:'Clauses',
 s:'___ es morgen regnet, bleiben wir zu Hause.',a:'Wenn',o:['Ob','Als','Wann'],
 ex:'A real condition about tomorrow → wenn (or falls). ob means "whether".',
 tr:'If it rains tomorrow, we’ll stay at home.',say:'Wenn es morgen regnet, bleiben wir zu Hause.'},
{gid:'konditional',lv:4,sk:'Clauses',
 s:'Ich weiß nicht, ___ er heute überhaupt kommt.',a:'ob',o:['wenn','falls','als'],
 ex:'English "if" after wissen means "whether" → ob, never wenn.',
 tr:'I don’t know if he’s coming at all today.',say:'Ich weiß nicht, ob er heute überhaupt kommt.'},
{gid:'konditional',lv:4,sk:'Clauses',
 s:'___ Sie Fragen haben, wenden Sie sich bitte an unser Büro.',a:'Falls',o:['Ob','Als','Wann'],
 ex:'falls = "in case", a shade more open than wenn, and typical of formal written German.',
 tr:'If you have questions, please contact our office.',say:'Falls Sie Fragen haben, wenden Sie sich bitte an unser Büro.'},
{gid:'konditional',lv:4,sk:'Clauses',
 s:'___ du Zeit, komm einfach vorbei.',a:'Hast',o:['Hättest','Haben','Wenn hast'],
 ex:'The wenn-less conditional: the verb takes position 1. „Hast du Zeit, komm vorbei“ = „Wenn du Zeit hast, komm vorbei“.',
 tr:'If you have time, just drop by.',say:'Hast du Zeit, komm einfach vorbei.'},
{gid:'konditional',lv:4,sk:'Clauses',
 s:'Wenn ich mehr Geld ___, würde ich eine Weltreise machen.',a:'hätte',o:['habe','haben würde','hatte'],
 ex:'Unreal condition → Konjunktiv II in the wenn-clause, and the short form hätte, not "haben würde".',
 tr:'If I had more money, I’d travel round the world.',say:'Wenn ich mehr Geld hätte, würde ich eine Weltreise machen.'},
{gid:'konditional',lv:4,sk:'Clauses',
 s:'Wenn du den Vertrag unterschreibst, ___ du dich für zwei Jahre.',a:'bindest',o:['du bindest','bindet','binden'],
 ex:'The wenn-clause fills position 1, so the main verb comes immediately after the comma: bindest du dich.',
 tr:'If you sign the contract, you tie yourself down for two years.',say:'Wenn du den Vertrag unterschreibst, bindest du dich für zwei Jahre.'},
{gid:'konditional',lv:4,sk:'Clauses',
 s:'Wenn ich du ___, würde ich das Angebot ablehnen.',a:'wäre',o:['bin','sein würde','war'],
 ex:'The fixed phrase for advice: „Wenn ich du wäre …“ — Konjunktiv II of sein.',
 tr:'If I were you, I’d turn the offer down.',say:'Wenn ich du wäre, würde ich das Angebot ablehnen.'},
{gid:'konditional',lv:4,sk:'Clauses',
 s:'Falls du nicht kommen ___, schreib mir bitte eine Nachricht.',a:'kannst',o:['kann','können','gekonnt'],
 ex:'In a falls-clause the modal is the conjugated verb and goes last, after the infinitive: nicht kommen kannst.',
 tr:'In case you can’t come, please send me a message.',say:'Falls du nicht kommen kannst, schreib mir bitte eine Nachricht.'},

/* --- passiv-basis --- */
{gid:'passiv-basis',lv:4,sk:'Passive',
 s:'Das Haus ___ im Moment renoviert.',a:'wird',o:['ist','hat','werden'],
 ex:'Passive Präsens = werden + Partizip II. Singular subject → wird.',
 tr:'The house is being renovated at the moment.',say:'Das Haus wird im Moment renoviert.'},
{gid:'passiv-basis',lv:4,sk:'Passive',
 s:'Die Fenster ___ jeden Monat geputzt.',a:'werden',o:['wird','sind','haben'],
 ex:'The subject die Fenster is plural, so werden agrees with it. Partizip II never changes.',
 tr:'The windows are cleaned every month.',say:'Die Fenster werden jeden Monat geputzt.'},
{gid:'passiv-basis',lv:4,sk:'Passive',
 s:'Der Film ___ 1998 in Berlin gedreht.',a:'wurde',o:['wird','war','hat'],
 ex:'A finished action in the past, passive → Präteritum of werden: wurde.',
 tr:'The film was shot in Berlin in 1998.',say:'Der Film wurde 1998 in Berlin gedreht.'},
{gid:'passiv-basis',lv:4,sk:'Passive',
 s:'Das Formular wird ___ der Chefin unterschrieben.',a:'von',o:['durch','mit','bei'],
 ex:'A person who acts = the agent → von + Dativ.',
 tr:'The form is signed by the boss.',say:'Das Formular wird von der Chefin unterschrieben.'},
{gid:'passiv-basis',lv:4,sk:'Passive',
 s:'Die Straße wurde ___ das Unwetter beschädigt.',a:'durch',o:['von','mit','für'],
 ex:'A cause or means, not a conscious actor → durch + Akkusativ.',
 tr:'The road was damaged by the storm.',say:'Die Straße wurde durch das Unwetter beschädigt.'},
{gid:'passiv-basis',lv:4,sk:'Passive',
 s:'___ wurde von der Bank leider nicht geholfen.',a:'Mir',o:['Ich','Mich','Meiner'],
 ex:'helfen takes Dativ, and the passive cannot change that: Mir wurde geholfen — never "Ich wurde geholfen".',
 tr:'I wasn’t helped by the bank, unfortunately.',say:'Mir wurde von der Bank leider nicht geholfen.'},
{gid:'passiv-basis',lv:4,sk:'Passive',
 s:'Die Brücke ist erst letztes Jahr gebaut ___.',a:'worden',o:['geworden','werden','wurde'],
 ex:'In the passive Perfekt the Partizip II of werden is worden, without ge-.',
 tr:'The bridge was only built last year.',say:'Die Brücke ist erst letztes Jahr gebaut worden.'},
{gid:'passiv-basis',lv:4,sk:'Passive',
 s:'Diese Aufgabe muss bis Freitag ___ werden.',a:'erledigt',o:['erledigen','zu erledigen','erledigte'],
 ex:'Modal + passive infinitive = Partizip II + werden: muss erledigt werden.',
 tr:'This task has to be finished by Friday.',say:'Diese Aufgabe muss bis Freitag erledigt werden.'},

/* --- konjunktiv2-basis --- */
{gid:'konjunktiv2-basis',lv:4,sk:'Konjunktiv',
 s:'___ Sie mir bitte beim Formular helfen?',a:'Könnten',o:['Konnten','Könntet','Könnte'],
 ex:'Polite request with Sie → Könnten. Konnten is the past indicative, könntet belongs to ihr.',
 tr:'Could you help me with the form, please?',say:'Könnten Sie mir bitte beim Formular helfen?'},
{gid:'konjunktiv2-basis',lv:4,sk:'Konjunktiv',
 s:'Ich ___ gern eine Tasse Tee.',a:'hätte',o:['habe','hatte','hättest'],
 ex:'„Ich hätte gern …“ is the standard polite way to order. „Ich habe gern Tee“ would mean "I like tea".',
 tr:'I’d like a cup of tea.',say:'Ich hätte gern eine Tasse Tee.'},
{gid:'konjunktiv2-basis',lv:4,sk:'Konjunktiv',
 s:'An deiner Stelle ___ ich das Auto nicht kaufen.',a:'würde',o:['werde','wurde','würdest'],
 ex:'Advice with würde + Infinitiv, first person: würde ich. The adverbial in position 1 pushes the verb to position 2.',
 tr:'In your position I wouldn’t buy the car.',say:'An deiner Stelle würde ich das Auto nicht kaufen.'},
{gid:'konjunktiv2-basis',lv:4,sk:'Konjunktiv',
 s:'Es ___ schön, dich mal wiederzusehen.',a:'wäre',o:['war','wird','wären'],
 ex:'A soft wish about something not (yet) real → wäre, the Konjunktiv II of sein.',
 tr:'It would be nice to see you again sometime.',say:'Es wäre schön, dich mal wiederzusehen.'},
{gid:'konjunktiv2-basis',lv:4,sk:'Konjunktiv',
 s:'___ ich kurz Ihr Telefon benutzen?',a:'Dürfte',o:['Durfte','Dürften','Dürftest'],
 ex:'Very polite permission in the first person singular → Dürfte ich. Durfte is past indicative.',
 tr:'Might I use your phone for a moment?',say:'Dürfte ich kurz Ihr Telefon benutzen?'},
{gid:'konjunktiv2-basis',lv:4,sk:'Konjunktiv',
 s:'Du ___ wirklich mehr schlafen.',a:'solltest',o:['sollst','solltet','sollte'],
 ex:'Advice, not an order → Konjunktiv II solltest. sollst would sound like someone else’s instruction.',
 tr:'You really should sleep more.',say:'Du solltest wirklich mehr schlafen.'},
{gid:'konjunktiv2-basis',lv:4,sk:'Konjunktiv',
 s:'Ich ___ nicht, was ich ohne deine Hilfe gemacht hätte.',a:'wüsste',o:['weiß','wusste','wissen würde'],
 ex:'wissen has its own Konjunktiv II: wüsste. No würde-form is needed for it.',
 tr:'I wouldn’t know what I’d have done without your help.',say:'Ich wüsste nicht, was ich ohne deine Hilfe gemacht hätte.'},
{gid:'konjunktiv2-basis',lv:4,sk:'Konjunktiv',
 s:'Es wäre besser, wenn wir früher ___ würden.',a:'anfangen',o:['anfingen','angefangen','anzufangen'],
 ex:'würde + Infinitiv: the infinitive anfangen stands before würden at the end of the wenn-clause.',
 tr:'It would be better if we started earlier.',say:'Es wäre besser, wenn wir früher anfangen würden.'},

/* --- relativ-was-wo --- */
{gid:'relativ-was-wo',lv:4,sk:'Clauses',
 s:'Alles, ___ du sagst, klingt logisch.',a:'was',o:['das','dass','welches'],
 ex:'After alles there is no noun with a gender → was.',
 tr:'Everything you say sounds logical.',say:'Alles, was du sagst, klingt logisch.'},
{gid:'relativ-was-wo',lv:4,sk:'Clauses',
 s:'Es gibt nichts, ___ mich so stört wie Lärm.',a:'was',o:['das','der','dem'],
 ex:'nichts, etwas, alles and vieles always take was as the relative pronoun.',
 tr:'There is nothing that bothers me as much as noise.',say:'Es gibt nichts, was mich so stört wie Lärm.'},
{gid:'relativ-was-wo',lv:4,sk:'Clauses',
 s:'Er hat sich nicht entschuldigt, ___ ich wirklich unhöflich finde.',a:'was',o:['das','dass','welches'],
 ex:'Here the relative clause refers back to the whole previous sentence → was.',
 tr:'He didn’t apologise, which I find really rude.',say:'Er hat sich nicht entschuldigt, was ich wirklich unhöflich finde.'},
{gid:'relativ-was-wo',lv:4,sk:'Clauses',
 s:'Das ist das Beste, ___ mir diese Woche passiert ist.',a:'was',o:['das','dem','welches'],
 ex:'After a neuter superlative (das Beste, das Schönste, das Einzige) the pronoun is was.',
 tr:'That’s the best thing that has happened to me this week.',say:'Das ist das Beste, was mir diese Woche passiert ist.'},
{gid:'relativ-was-wo',lv:4,sk:'Clauses',
 s:'Das Dorf, ___ ich aufgewachsen bin, liegt in den Bergen.',a:'wo',o:['das','wohin','woher'],
 ex:'A place with no movement → wo, short for "in dem". wohin is for movement towards.',
 tr:'The village where I grew up is in the mountains.',say:'Das Dorf, wo ich aufgewachsen bin, liegt in den Bergen.'},
{gid:'relativ-was-wo',lv:4,sk:'Clauses',
 s:'Das ist ein Thema, ___ wir noch diskutieren müssen.',a:'worüber',o:['über was','was über','darüber'],
 ex:'diskutieren über + was fuse into the wo(r)-word worüber. „über was“ is avoided in careful German.',
 tr:'That’s a topic we still have to discuss.',say:'Das ist ein Thema, worüber wir noch diskutieren müssen.'},
{gid:'relativ-was-wo',lv:4,sk:'Clauses',
 s:'Der Kurs, ___ ich dir empfohlen habe, beginnt im Mai.',a:'den',o:['was','dem','wo'],
 ex:'Here there IS a noun: der Kurs, masculine, and it is the accusative object of empfehlen → den.',
 tr:'The course I recommended to you starts in May.',say:'Der Kurs, den ich dir empfohlen habe, beginnt im Mai.'},
{gid:'relativ-was-wo',lv:4,sk:'Clauses',
 s:'Die Leute, ___ ich geholfen habe, haben sich nicht bedankt.',a:'denen',o:['die','was','dem'],
 ex:'helfen takes Dativ, and the noun is plural → denen, the one relative form that differs from the article.',
 tr:'The people I helped didn’t say thank you.',say:'Die Leute, denen ich geholfen habe, haben sich nicht bedankt.'}
,

/* --- adjektiv-komplett --- */
{gid:'adjektiv-komplett',lv:4,sk:'Adjectives',
 s:'Ich habe ein ___ Buch gelesen.',a:'interessantes',o:['interessante','interessanter','interessanten'],
 ex:'After ein (neuter), the article shows nothing, so the adjective borrows the das-ending: -es.',
 tr:'I read an interesting book.',say:'Ich habe ein interessantes Buch gelesen.'},
{gid:'adjektiv-komplett',lv:4,sk:'Adjectives',
 s:'Der ___ Mann von gegenüber hat uns geholfen.',a:'alte',o:['alter','alten','altes'],
 ex:'der already shows nominative masculine → weak ending -e.',
 tr:'The old man from across the street helped us.',say:'Der alte Mann von gegenüber hat uns geholfen.'},
{gid:'adjektiv-komplett',lv:4,sk:'Adjectives',
 s:'Ich fahre mit dem ___ Zug.',a:'nächsten',o:['nächste','nächster','nächstes'],
 ex:'dem shows Dativ, so the adjective is lazy — and outside the five -e boxes that means -en.',
 tr:'I’m taking the next train.',say:'Ich fahre mit dem nächsten Zug.'},
{gid:'adjektiv-komplett',lv:4,sk:'Adjectives',
 s:'Sie trinkt ___ Kaffee ohne Zucker.',a:'schwarzen',o:['schwarz','schwarzer','schwarzes'],
 ex:'No article at all → strong ending. Akkusativ masculine would be den, so the adjective takes -en.',
 tr:'She drinks black coffee without sugar.',say:'Sie trinkt schwarzen Kaffee ohne Zucker.'},
{gid:'adjektiv-komplett',lv:4,sk:'Adjectives',
 s:'Wir haben viele ___ Leute kennengelernt.',a:'junge',o:['jungen','junger','junges'],
 ex:'viele is not an article word, so the adjective after it is strong: Akkusativ plural → -e.',
 tr:'We got to know a lot of young people.',say:'Wir haben viele junge Leute kennengelernt.'},
{gid:'adjektiv-komplett',lv:4,sk:'Adjectives',
 s:'Mit ___ Freunden macht alles mehr Spaß.',a:'guten',o:['gute','guter','gutem'],
 ex:'No article, Dativ plural. The article would be den → strong ending -en.',
 tr:'With good friends everything is more fun.',say:'Mit guten Freunden macht alles mehr Spaß.'},
{gid:'adjektiv-komplett',lv:4,sk:'Adjectives',
 s:'Ich habe meiner ___ Schwester geholfen.',a:'kleinen',o:['kleine','kleiner','kleines'],
 ex:'meiner already shows Dativ feminine, so the adjective takes the lazy ending -en.',
 tr:'I helped my little sister.',say:'Ich habe meiner kleinen Schwester geholfen.'},
{gid:'adjektiv-komplett',lv:4,sk:'Adjectives',
 s:'Hast du keine ___ Idee?',a:'bessere',o:['besser','besseren','besserer'],
 ex:'Comparative plus ending: keine shows Akkusativ feminine, so besser takes the weak -e → bessere.',
 tr:'Haven’t you got a better idea?',say:'Hast du keine bessere Idee?'},

/* --- partizip-adjektiv-b1 --- */
{gid:'partizip-adjektiv-b1',lv:4,sk:'Adjectives',
 s:'Das ___ Kind suchte seine Mutter.',a:'weinende',o:['geweinte','weinend','weinen'],
 ex:'The child is doing the crying → Partizip I weinend + weak ending -e after das.',
 tr:'The crying child was looking for its mother.',say:'Das weinende Kind suchte seine Mutter.'},
{gid:'partizip-adjektiv-b1',lv:4,sk:'Adjectives',
 s:'Vorsicht, das ist ___ Wasser!',a:'kochendes',o:['gekochtes','kochend','gekocht'],
 ex:'It is boiling right now → Partizip I with the neuter strong ending: kochendes. gekochtes Wasser would be water that was boiled earlier.',
 tr:'Careful, that’s boiling water!',say:'Vorsicht, das ist kochendes Wasser!'},
{gid:'partizip-adjektiv-b1',lv:4,sk:'Adjectives',
 s:'Ich esse gern ___ Eier.',a:'gekochte',o:['kochende','gekocht','kochen'],
 ex:'Someone boiled them; the action is finished → Partizip II + plural ending -e.',
 tr:'I like eating boiled eggs.',say:'Ich esse gern gekochte Eier.'},
{gid:'partizip-adjektiv-b1',lv:4,sk:'Adjectives',
 s:'Die ___ Kinder sollen nicht geweckt werden.',a:'schlafenden',o:['geschlafenen','schlafend','schlafen'],
 ex:'schlafen is intransitive, so there is no attributive Partizip II. Partizip I + plural ending → schlafenden.',
 tr:'The sleeping children shouldn’t be woken up.',say:'Die schlafenden Kinder sollen nicht geweckt werden.'},
{gid:'partizip-adjektiv-b1',lv:4,sk:'Adjectives',
 s:'Hast du das ___ Formular schon abgeschickt?',a:'ausgefüllte',o:['ausfüllende','ausgefüllt','ausfüllen'],
 ex:'The form has been filled in — passive and finished → Partizip II + weak -e after das.',
 tr:'Have you already sent off the completed form?',say:'Hast du das ausgefüllte Formular schon abgeschickt?'},
{gid:'partizip-adjektiv-b1',lv:4,sk:'Adjectives',
 s:'Ein ___ Hund beißt nicht.',a:'bellender',o:['bellende','gebellter','bellend'],
 ex:'The dog barks itself → Partizip I, and after ein the masculine nominative needs -er.',
 tr:'A barking dog doesn’t bite.',say:'Ein bellender Hund beißt nicht.'},
{gid:'partizip-adjektiv-b1',lv:4,sk:'Adjectives',
 s:'Wir haben die ___ Gäste am Eingang begrüßt.',a:'eingeladenen',o:['einladenden','eingeladen','einladen'],
 ex:'They were invited by us → Partizip II eingeladen + plural ending -en after die.',
 tr:'We greeted the invited guests at the entrance.',say:'Wir haben die eingeladenen Gäste am Eingang begrüßt.'},
{gid:'partizip-adjektiv-b1',lv:4,sk:'Adjectives',
 s:'Mit dem ___ Fahrrad fahre ich wieder zur Arbeit.',a:'reparierten',o:['reparierenden','repariert','reparierend'],
 ex:'The bike was repaired → Partizip II. dem shows Dativ, so the ending is -en. Note: no ge- in repariert.',
 tr:'I ride to work again on the repaired bike.',say:'Mit dem reparierten Fahrrad fahre ich wieder zur Arbeit.'},

/* --- untrennbar --- */
{gid:'untrennbar',lv:4,sk:'Verbs',
 s:'Ich habe meine Großeltern am Wochenende ___.',a:'besucht',o:['gebesucht','besuchen','gebesuchen'],
 ex:'be- is inseparable and unstressed, so the Partizip II takes no ge-: besucht.',
 tr:'I visited my grandparents at the weekend.',say:'Ich habe meine Großeltern am Wochenende besucht.'},
{gid:'untrennbar',lv:4,sk:'Verbs',
 s:'Er hat die Aufgabe nicht ___.',a:'verstanden',o:['geverstanden','verstehen','verstandet'],
 ex:'ver- is inseparable → no ge-. The strong Partizip II of verstehen is verstanden.',
 tr:'He didn’t understand the task.',say:'Er hat die Aufgabe nicht verstanden.'},
{gid:'untrennbar',lv:4,sk:'Verbs',
 s:'Die Ärztin hat mir mehr Schlaf ___.',a:'empfohlen',o:['geempfohlen','empfehlen','empfohlt'],
 ex:'emp- is inseparable, and empfehlen is strong: empfohlen, with no ge-.',
 tr:'The doctor recommended more sleep to me.',say:'Die Ärztin hat mir mehr Schlaf empfohlen.'},
{gid:'untrennbar',lv:4,sk:'Verbs',
 s:'Der Sturm hat das halbe Dach ___.',a:'zerstört',o:['gezerstört','zerstören','zerstörte'],
 ex:'zer- is inseparable → zerstört. The regular -t ending is enough; no ge- is added.',
 tr:'The storm destroyed half the roof.',say:'Der Sturm hat das halbe Dach zerstört.'},
{gid:'untrennbar',lv:4,sk:'Verbs',
 s:'Ich habe das Fenster schon ___.',a:'aufgemacht',o:['aufmacht','aufmachen','gemachtauf'],
 ex:'auf- is separable and stressed, so ge- goes in the middle: auf-ge-macht.',
 tr:'I’ve already opened the window.',say:'Ich habe das Fenster schon aufgemacht.'},
{gid:'untrennbar',lv:4,sk:'Verbs',
 s:'Wir ___ nächsten Monat in eine größere Wohnung um.',a:'ziehen',o:['umziehen','zieht','gezogen'],
 ex:'umziehen (to move house) is separable, so the prefix um stands at the end and only ziehen is conjugated.',
 tr:'Next month we’re moving to a bigger flat.',say:'Wir ziehen nächsten Monat in eine größere Wohnung um.'},
{gid:'untrennbar',lv:4,sk:'Verbs',
 s:'Hast du den Vertrag schon ___?',a:'übersetzt',o:['übergesetzt','geübersetzt','übersetzen'],
 ex:'übersetzen in the sense "translate" is inseparable and stressed on the stem → übersetzt, no ge-.',
 tr:'Have you translated the contract yet?',say:'Hast du den Vertrag schon übersetzt?'},
{gid:'untrennbar',lv:4,sk:'Verbs',
 s:'Ich habe völlig vergessen, dich ___.',a:'anzurufen',o:['zu anrufen','anrufen zu','zu angerufen'],
 ex:'vergessen is inseparable (no ge-), but anrufen is separable, so zu goes inside: an-zu-rufen.',
 tr:'I completely forgot to call you.',say:'Ich habe völlig vergessen, dich anzurufen.'},

/* --- verbvalenz --- */
{gid:'verbvalenz',lv:4,sk:'Cases',
 s:'Ich helfe ___ gern bei den Hausaufgaben.',a:'dir',o:['dich','du','deiner'],
 ex:'helfen is a Dativ verb, however English says it. Dativ of du = dir.',
 tr:'I’ll gladly help you with your homework.',say:'Ich helfe dir gern bei den Hausaufgaben.'},
{gid:'verbvalenz',lv:4,sk:'Cases',
 s:'Dieser Vorschlag gefällt ___ überhaupt nicht.',a:'mir',o:['mich','ich','meiner'],
 ex:'gefallen takes Dativ: the thing pleases "to me". The proposal is the subject.',
 tr:'I don’t like this proposal at all.',say:'Dieser Vorschlag gefällt mir überhaupt nicht.'},
{gid:'verbvalenz',lv:4,sk:'Cases',
 s:'Ich danke ___ herzlich für die Einladung.',a:'Ihnen',o:['Sie','Ihr','Ihrer'],
 ex:'danken + Dativ. The polite Dativ form of Sie is Ihnen.',
 tr:'Thank you very much for the invitation.',say:'Ich danke Ihnen herzlich für die Einladung.'},
{gid:'verbvalenz',lv:4,sk:'Cases',
 s:'Wir warten schon zwanzig Minuten ___ den Bus.',a:'auf',o:['für','an','über'],
 ex:'warten has a fixed prepositional object: warten auf + Akkusativ.',
 tr:'We’ve been waiting twenty minutes for the bus.',say:'Wir warten schon zwanzig Minuten auf den Bus.'},
{gid:'verbvalenz',lv:4,sk:'Cases',
 s:'Kannst du ___ bitte den Weg zeigen?',a:'mir',o:['mich','ich','meiner'],
 ex:'zeigen takes two objects: person in Dativ (mir), thing in Akkusativ (den Weg).',
 tr:'Can you show me the way, please?',say:'Kannst du mir bitte den Weg zeigen?'},
{gid:'verbvalenz',lv:4,sk:'Cases',
 s:'Mein Chef hat ___ eine neue Stelle angeboten.',a:'mir',o:['mich','ich','meinen'],
 ex:'anbieten follows the pattern jmdm. etw. anbieten → Dativ person, Akkusativ thing.',
 tr:'My boss offered me a new job.',say:'Mein Chef hat mir eine neue Stelle angeboten.'},
{gid:'verbvalenz',lv:4,sk:'Cases',
 s:'Ich interessiere ___ sehr für Geschichte.',a:'mich',o:['mir','sich','mein'],
 ex:'sich interessieren is reflexive with Akkusativ, plus the fixed preposition für + Akkusativ.',
 tr:'I’m very interested in history.',say:'Ich interessiere mich sehr für Geschichte.'},
{gid:'verbvalenz',lv:4,sk:'Cases',
 s:'Ich habe mich sehr ___ dein Geschenk gefreut.',a:'über',o:['auf','von','für'],
 ex:'sich freuen über + Akkusativ for something that has happened; sich freuen auf is for something still to come.',
 tr:'I was really pleased about your present.',say:'Ich habe mich sehr über dein Geschenk gefreut.'},

/* --- negation-stellung --- */
{gid:'negation-stellung',lv:4,sk:'Sentences',
 s:'Ich habe das Buch ___ gelesen.',a:'nicht',o:['kein','keine','nichts'],
 ex:'A noun with das keeps nicht, and nicht stands directly before the Partizip II.',
 tr:'I haven’t read the book.',say:'Ich habe das Buch nicht gelesen.'},
{gid:'negation-stellung',lv:4,sk:'Sentences',
 s:'Ich kann dir heute leider ___.',a:'nicht helfen',o:['helfen nicht','nicht zu helfen','kein helfen'],
 ex:'nicht must stand before the infinitive at the end of the sentence.',
 tr:'Unfortunately I can’t help you today.',say:'Ich kann dir heute leider nicht helfen.'},
{gid:'negation-stellung',lv:4,sk:'Sentences',
 s:'Ich habe ___ Lust auf diese Diskussion.',a:'keine',o:['nicht','nicht die','kein'],
 ex:'A bare noun without an article is negated with kein. Lust is feminine → keine.',
 tr:'I don’t feel like having this discussion.',say:'Ich habe keine Lust auf diese Diskussion.'},
{gid:'negation-stellung',lv:4,sk:'Sentences',
 s:'Sie hat mich gestern ___.',a:'nicht angerufen',o:['angerufen nicht','nicht anrufen','nicht gerufen an'],
 ex:'nicht goes before the Partizip II, and the Partizip II of the separable anrufen is angerufen.',
 tr:'She didn’t call me yesterday.',say:'Sie hat mich gestern nicht angerufen.'},
{gid:'negation-stellung',lv:4,sk:'Sentences',
 s:'___ alle Kollegen waren mit dem Plan einverstanden.',a:'Nicht',o:['Kein','Keine','Nichts'],
 ex:'Partial negation: nicht jumps in front of the exact word it attacks — here alle.',
 tr:'Not all colleagues agreed with the plan.',say:'Nicht alle Kollegen waren mit dem Plan einverstanden.'},
{gid:'negation-stellung',lv:4,sk:'Sentences',
 s:'Ich habe ___ gesehen.',a:'ihn nicht',o:['nicht ihn','kein ihn','nicht gesehen ihn'],
 ex:'Unstressed pronouns always come before nicht: ihn nicht gesehen.',
 tr:'I didn’t see him.',say:'Ich habe ihn nicht gesehen.'},
{gid:'negation-stellung',lv:4,sk:'Sentences',
 s:'Du musst dich dafür ___.',a:'nicht entschuldigen',o:['entschuldigen nicht','nicht zu entschuldigen','kein entschuldigen'],
 ex:'Modal + reflexive + negation: nicht still stands just before the infinitive at the end.',
 tr:'You don’t have to apologise for that.',say:'Du musst dich dafür nicht entschuldigen.'},
{gid:'negation-stellung',lv:4,sk:'Sentences',
 s:'Es tut mir leid, dass ich ___ helfen konnte.',a:'dir nicht',o:['nicht dir','dich nicht','nicht dich'],
 ex:'In a subordinate clause the rule is the same: Dativ pronoun first, then nicht, then the verbs at the end.',
 tr:'I’m sorry that I couldn’t help you.',say:'Es tut mir leid, dass ich dir nicht helfen konnte.'},

/* --- substantivierung --- */
{gid:'substantivierung',lv:4,sk:'Style',
 s:'___ ist gesünder als Joggen.',a:'Schwimmen',o:['schwimmen','Das schwimmen','Schwimmend'],
 ex:'A nominalised infinitive is written with a capital letter; the article das may be left out as a subject.',
 tr:'Swimming is healthier than jogging.',say:'Schwimmen ist gesünder als Joggen.'},
{gid:'substantivierung',lv:4,sk:'Style',
 s:'___ Kochen höre ich immer Podcasts.',a:'Beim',o:['Bei','Am','Im'],
 ex:'bei + dem = beim + nominalised infinitive, the standard way to say "while doing".',
 tr:'When I cook I always listen to podcasts.',say:'Beim Kochen höre ich immer Podcasts.'},
{gid:'substantivierung',lv:4,sk:'Style',
 s:'Hast du ___ Neues von ihm gehört?',a:'etwas',o:['etwa','ein','eine'],
 ex:'etwas / nichts / viel / wenig + capitalised adjective with -es is the fixed pattern.',
 tr:'Have you heard anything new from him?',say:'Hast du etwas Neues von ihm gehört?'},
{gid:'substantivierung',lv:4,sk:'Style',
 s:'Ich habe im Archiv nichts ___ gefunden.',a:'Interessantes',o:['Interessante','interessantes','Interessanten'],
 ex:'After nichts the adjective becomes a neuter noun: capital letter plus the strong ending -es.',
 tr:'I found nothing interesting in the archive.',say:'Ich habe im Archiv nichts Interessantes gefunden.'},
{gid:'substantivierung',lv:4,sk:'Style',
 s:'Das ___ an diesem Job ist das Team.',a:'Beste',o:['Bester','beste','Bestes'],
 ex:'After das the nominalised superlative takes the weak ending -e: das Beste.',
 tr:'The best thing about this job is the team.',say:'Das Beste an diesem Job ist das Team.'},
{gid:'substantivierung',lv:4,sk:'Style',
 s:'Mein neuer Nachbar ist ___.',a:'Deutscher',o:['Deutsche','ein Deutsche','deutscher'],
 ex:'A nationality as a noun keeps its adjective ending: masculine with no article → Deutscher.',
 tr:'My new neighbour is German.',say:'Mein neuer Nachbar ist Deutscher.'},
{gid:'substantivierung',lv:4,sk:'Style',
 s:'Nach dem ___ gehe ich immer kurz spazieren.',a:'Essen',o:['essen','Esse','gegessen'],
 ex:'nach dem + nominalised infinitive: capitalised, neuter, unchanged in form.',
 tr:'After eating I always go for a short walk.',say:'Nach dem Essen gehe ich immer kurz spazieren.'},
{gid:'substantivierung',lv:4,sk:'Style',
 s:'Wir haben viel ___ über die Stadt gehört.',a:'Gutes',o:['Gute','gutes','Guten'],
 ex:'viel behaves like etwas/nichts → neuter noun with -es: viel Gutes. (But: alles Gute, with -e.)',
 tr:'We’ve heard a lot of good things about the city.',say:'Wir haben viel Gutes über die Stadt gehört.'},

/* --- vergleichssaetze --- */
{gid:'vergleichssaetze',lv:4,sk:'Clauses',
 s:'Berlin ist deutlich größer ___ Hamburg.',a:'als',o:['wie','als wie','so wie'],
 ex:'A comparative always takes als. "größer wie" is wrong in every exam.',
 tr:'Berlin is considerably bigger than Hamburg.',say:'Berlin ist deutlich größer als Hamburg.'},
{gid:'vergleichssaetze',lv:4,sk:'Clauses',
 s:'Sie ist genauso alt ___ ich.',a:'wie',o:['als','dass','denn'],
 ex:'Equality after so / genauso / fast so → wie.',
 tr:'She is exactly as old as I am.',say:'Sie ist genauso alt wie ich.'},
{gid:'vergleichssaetze',lv:4,sk:'Clauses',
 s:'___ mehr man übt, desto leichter wird es.',a:'Je',o:['Wie','Als','Umso'],
 ex:'The pair is je … desto (or je … umso). umso can only stand in the second half.',
 tr:'The more you practise, the easier it gets.',say:'Je mehr man übt, desto leichter wird es.'},
{gid:'vergleichssaetze',lv:4,sk:'Clauses',
 s:'Je mehr ich lese, ___ besser schreibe ich.',a:'desto',o:['je','als','wie'],
 ex:'desto introduces the main clause: comparative first, then the verb in second position.',
 tr:'The more I read, the better I write.',say:'Je mehr ich lese, desto besser schreibe ich.'},
{gid:'vergleichssaetze',lv:4,sk:'Clauses',
 s:'Er tut so, ___ er alles besser wüsste.',a:'als ob',o:['als wie','wie ob','so dass'],
 ex:'An unreal comparison → als ob + Konjunktiv II (wüsste).',
 tr:'He acts as if he knew everything better.',say:'Er tut so, als ob er alles besser wüsste.'},
{gid:'vergleichssaetze',lv:4,sk:'Clauses',
 s:'Es war so laut, ___ ich nichts verstanden habe.',a:'dass',o:['sodass','als','wie'],
 ex:'The so is already in the main clause, so the consequence clause begins with dass alone.',
 tr:'It was so loud that I didn’t understand anything.',say:'Es war so laut, dass ich nichts verstanden habe.'},
{gid:'vergleichssaetze',lv:4,sk:'Clauses',
 s:'Je länger die Sitzung dauerte, desto nervöser ___ alle.',a:'wurden',o:['wurde','werden','geworden'],
 ex:'In the desto-half the verb takes position 2 and agrees with the plural subject alle → wurden.',
 tr:'The longer the meeting lasted, the more nervous everyone got.',say:'Je länger die Sitzung dauerte, desto nervöser wurden alle.'},
{gid:'vergleichssaetze',lv:4,sk:'Clauses',
 s:'Der Bus kam zu spät, ___ wir den Film verpasst haben.',a:'sodass',o:['damit','als ob','obwohl'],
 ex:'An unintended consequence → sodass. damit would mean we missed it on purpose.',
 tr:'The bus came late, so that we missed the film.',say:'Der Bus kam zu spät, sodass wir den Film verpasst haben.'},

/* --- modalpartikel-basis --- */
{gid:'modalpartikel-basis',lv:4,sk:'Style',
 s:'Wie heißt du ___?',a:'denn',o:['ja','eben','mal'],
 ex:'In a question, friendly interest is carried by denn. ja and eben cannot stand in a question like this.',
 tr:'So what’s your name?',say:'Wie heißt du denn?'},
{gid:'modalpartikel-basis',lv:4,sk:'Style',
 s:'Das habe ich dir ___ letzte Woche erklärt!',a:'doch',o:['denn','wohl','mal'],
 ex:'doch reminds the listener of something they already know. denn is impossible in a statement.',
 tr:'But I explained that to you last week!',say:'Das habe ich dir doch letzte Woche erklärt!'},
{gid:'modalpartikel-basis',lv:4,sk:'Style',
 s:'Ruf mich ___ an, wenn du Zeit hast.',a:'mal',o:['denn','wohl','eben'],
 ex:'mal takes the weight out of a request — "give me a call sometime".',
 tr:'Give me a call sometime when you have time.',say:'Ruf mich mal an, wenn du Zeit hast.'},
{gid:'modalpartikel-basis',lv:4,sk:'Style',
 s:'Du weißt ___, dass ich das nicht mag.',a:'ja',o:['denn','mal','wohl'],
 ex:'ja marks shared knowledge: "as you know".',
 tr:'You know, after all, that I don’t like that.',say:'Du weißt ja, dass ich das nicht mag.'},
{gid:'modalpartikel-basis',lv:4,sk:'Style',
 s:'Ich kann nichts machen — das ist ___ so.',a:'eben',o:['denn','mal','wohl'],
 ex:'eben expresses resignation: that is simply how things are.',
 tr:'I can’t do anything — that’s just how it is.',say:'Ich kann nichts machen — das ist eben so.'},
{gid:'modalpartikel-basis',lv:4,sk:'Style',
 s:'Gib ___ das Buch!',a:'mir mal',o:['mal mir','mich mal','mal mich'],
 ex:'Pronoun first, particle after it: Gib mir mal das Buch. And geben takes Dativ for the person.',
 tr:'Just give me the book!',say:'Gib mir mal das Buch!'},
{gid:'modalpartikel-basis',lv:4,sk:'Style',
 s:'Komm ___ mit ins Kino, es wird lustig!',a:'doch',o:['denn','wohl','ja'],
 ex:'doch in an imperative turns an order into a warm invitation.',
 tr:'Do come to the cinema with us, it’ll be fun!',say:'Komm doch mit ins Kino, es wird lustig!'},
{gid:'modalpartikel-basis',lv:4,sk:'Style',
 s:'Probier es ___ mit weniger Zucker!',a:'doch mal',o:['mal doch','denn mal','doch denn'],
 ex:'When two particles stack, the order is fixed: doch mal, never mal doch.',
 tr:'Why not try it with less sugar!',say:'Probier es doch mal mit weniger Zucker!'},

/* --- textkohaesion --- */
{gid:'textkohaesion',lv:4,sk:'Style',
 s:'Ich habe ein Fahrrad gekauft. ___ war überraschend günstig.',a:'Es',o:['Er','Sie','Ihn'],
 ex:'The pronoun takes the gender of the German noun: das Fahrrad → es.',
 tr:'I bought a bike. It was surprisingly cheap.',say:'Ich habe ein Fahrrad gekauft. Es war überraschend günstig.'},
{gid:'textkohaesion',lv:4,sk:'Style',
 s:'Das Kind ist krank. ___ muss im Bett bleiben.',a:'Es',o:['Er','Sie','Das es'],
 ex:'das Kind is neuter, so the pronoun is es — grammatical gender wins over natural gender.',
 tr:'The child is ill. He has to stay in bed.',say:'Das Kind ist krank. Es muss im Bett bleiben.'},
{gid:'textkohaesion',lv:4,sk:'Style',
 s:'Ich habe keinen Führerschein. ___ fahre ich immer mit dem Rad.',a:'Deshalb',o:['Trotzdem','Außerdem','Allerdings'],
 ex:'A consequence of the previous sentence → deshalb, and in position 1 it pushes the verb to position 2.',
 tr:'I don’t have a driving licence. That’s why I always cycle.',say:'Ich habe keinen Führerschein. Deshalb fahre ich immer mit dem Rad.'},
{gid:'textkohaesion',lv:4,sk:'Style',
 s:'Die Wohnung ist wirklich schön. ___ ist sie zu teuer.',a:'Allerdings',o:['Deshalb','Danach','Außerdem'],
 ex:'The second sentence restricts the praise → allerdings, the polite way to say "however".',
 tr:'The flat is really nice. It’s too expensive, though.',say:'Die Wohnung ist wirklich schön. Allerdings ist sie zu teuer.'},
{gid:'textkohaesion',lv:4,sk:'Style',
 s:'Zuerst habe ich gefrühstückt. ___ bin ich zur Arbeit gefahren.',a:'Danach',o:['Deshalb','Allerdings','Trotzdem'],
 ex:'A step in a sequence → danach. It pairs naturally with zuerst.',
 tr:'First I had breakfast. After that I drove to work.',say:'Zuerst habe ich gefrühstückt. Danach bin ich zur Arbeit gefahren.'},
{gid:'textkohaesion',lv:4,sk:'Style',
 s:'Der Kurs ist gut organisiert. ___ ist er ziemlich günstig.',a:'Außerdem',o:['Allerdings','Trotzdem','Danach'],
 ex:'A second point in the same direction → außerdem. allerdings would signal a contrast.',
 tr:'The course is well organised. Besides, it’s quite cheap.',say:'Der Kurs ist gut organisiert. Außerdem ist er ziemlich günstig.'},
{gid:'textkohaesion',lv:4,sk:'Style',
 s:'Wir haben lange über das Problem gesprochen. ___ konnten wir uns nicht einigen.',a:'Darüber',o:['Dafür','Davon','Damit'],
 ex:'sich einigen über + the known topic → the da-compound darüber, placed in position 1 as the link.',
 tr:'We talked about the problem for a long time. We couldn’t agree on it.',say:'Wir haben lange über das Problem gesprochen. Darüber konnten wir uns nicht einigen.'},
{gid:'textkohaesion',lv:4,sk:'Style',
 s:'Er hat sich nie entschuldigt. ___ habe ich ihm verziehen.',a:'Trotzdem',o:['Deshalb','Außerdem','Danach'],
 ex:'Concession between two sentences → trotzdem in position 1, verb second: Trotzdem habe ich …',
 tr:'He never apologised. I forgave him anyway.',say:'Er hat sich nie entschuldigt. Trotzdem habe ich ihm verziehen.'}
];
